def _metadata_version(default: str = "8.0.0") -> str:
    try:
        text = (PLUGIN_DIR / "metadata.yaml").read_text(encoding="utf-8")
        match = re.search(r"(?m)^version:\s*(.+?)\s*$", text)
        if match:
            return match.group(1).strip().strip("\"'")
    except Exception:
        pass
    return default


