@lru_cache(maxsize=8192)
def _cached_normalize_profile_match_key(text: str) -> str:
    text = str(text or "").strip().lower()
    text = re.sub(r"\.(safetensors|ckpt|pt|bin)$", "", text, flags=re.I)
    return re.sub(r"[^0-9a-z\u3040-\u30ff\u3400-\u9fff]+", "", text)


@lru_cache(maxsize=8192)
def _cached_normalize_lora_match_key(text: str) -> str:
    text = str(text or "").strip().replace("\\", "/").split("/")[-1].lower()
    text = re.sub(r"\.(safetensors|ckpt|pt|bin)$", "", text, flags=re.I)
    text = text.replace("＿", "_").replace("－", "-").replace("—", "-").replace("–", "-")
    return re.sub(r"[\s_\-\.]+", "", text)

