def _build_zipcrypto_crc_table() -> tuple:
    table = []
    for i in range(256):
        value = i
        for _ in range(8):
            if value & 1:
                value = 0xEDB88320 ^ (value >> 1)
            else:
                value >>= 1
        table.append(value & 0xFFFFFFFF)
    return tuple(table)


ZIPCRYPTO_CRC_TABLE = _build_zipcrypto_crc_table()

