        self._test_mode_log_handler = None
        self._test_mode_log_tasks = set()
        self._test_mode_log_dedupe = {}
        self._test_mode_sending = False
        self._look_private_image_cache = {}
        self._look_private_image_waiters = {}
        self._look_private_image_lock = asyncio.Lock()
        self._look_recent_session_image_cache = {}
        self._look_recent_session_image_lock = asyncio.Lock()
        self._saved_prompt_pending = {}
        self._saved_prompt_lock = asyncio.Lock()
        self._json_file_cache = {}
        self._checkpoint_names_runtime_cache = {}
        self._look_private_history_log_cache = {}
        self._load_test_mode_state()
        self._install_test_mode_log_handler()
        
        # ====== 4. 更新 UI 配置 ======
        self._auto_update_schema()
        self._migrate_stale_runtime_config()
        
        # Control 配置
        cmd_conf = config.get("command_settings", {}) or {}
        self.command_prefix = str(cmd_conf.get("prefix", "jh") or "jh").strip() or "jh"
        message_conf = config.get("message_settings", {}) or {}
        self.send_waiting_message = bool(message_conf.get("send_waiting_message", True))
        self.waiting_message = str(message_conf.get("waiting_message", "") or "").strip() or "🎨 正在为你绘图，请稍候..."
        self.auto_recall_generation_result = bool(message_conf.get("auto_recall_generation_result", False))
        self.auto_recall_delay_seconds = max(int(message_conf.get("auto_recall_delay_seconds", 180) or 180), 1)
        self._recall_tasks = set()
