    def _auto_update_schema(self):
        """扫描持久化目录，更新 WebUI 工作流和 LoRA 下拉列表。"""
        try:
            schema_path = PLUGIN_DIR / '_conf_schema.json'
            workflow_dir = self.data_dir / 'workflow'

            if not workflow_dir.exists():
                return

            files = sorted([
                f.name for f in workflow_dir.glob("*.json")
                if not f.name.endswith(".steps.json")
            ])

            if not files:
                files = ["workflow_api.json"]

            with open(schema_path, 'r', encoding='utf-8') as f:
                data = json.load(f)

            wf_target = data['workflow_settings']['items']['json_file']
            wf_target['options'] = files
            wf_target['enum'] = files

            model_family_items = data.get('model_family_settings', {}).get('items', {})
            illustrious_items = model_family_items.get('illustrious', {}).get('items', {})
            checkpoint_target = illustrious_items.get('checkpoint_name') if isinstance(illustrious_items, dict) else None
            checkpoint_options = self._schema_checkpoint_options()
            if isinstance(checkpoint_target, dict):
                checkpoint_target['description'] = "Illustrious Checkpoint（主模型）"
                checkpoint_target['hint'] = (
                    "这里选主模型 checkpoint，文件应放在 ComfyUI/models/checkpoints。"
                    "PerfectDeliberate 这类模型是 checkpoint，不会出现在角色 LoRA 或画风 LoRA 下拉里；"
                    "找不到时先刷新/重启 ComfyUI，或在 model_download.checkpoint_dir 填 AstrBot 能访问的 checkpoints 目录。"
                )
                checkpoint_target['options'] = checkpoint_options
                checkpoint_target.pop('enum', None)
            style_preset_target = illustrious_items.get('style_preset') if isinstance(illustrious_items, dict) else None
            if isinstance(style_preset_target, dict):
                style_preset_target['description'] = "Illustrious 内置画风预设"
                style_preset_target['hint'] = (
                    "default 使用普通 Illustrious 插画配置；切回 default 会把 PerfectDeliberate checkpoint 重置为普通 Illustrious。"
                    "perfectdeliberate_realism 会自动使用 "
                    "perfectdeliberate_v90.safetensors、Euler a、最终 960x1440、34 steps、CFG 6.8，"
                    "并限制角色 LoRA 强度；pvc 会使用 WAI + PVC 专用工作流和画风 LoRA 链；newpvc 会使用 Nova 3DCG + SSS/RIN 专用工作流；random 每次在内置画风里随机。"
                )
                style_preset_target['options'] = self._style_preset_options()
                style_preset_target['enum'] = self._style_preset_options()

            img2img_items = data.get('img2img_settings', {}).get('items', {})
            replace_wf_target = img2img_items.get('character_replace_workflow')
            if isinstance(replace_wf_target, dict):
                replace_wf_target['options'] = files
                replace_wf_target['enum'] = files

            # LoRA 列表来自 data_dir/lora_cache.json，由 /comfy_lora refresh 或初始化时从 ComfyUI API 获取。
            lora_options = [""]
            style_lora_options = [""]
            raw_cached_loras = []
            lora_cache_path = self.data_dir / "lora_cache.json"
            if lora_cache_path.exists():
                try:
                    cache = json.loads(lora_cache_path.read_text(encoding='utf-8'))
                    raw_cached_loras = cache.get("loras", []) if isinstance(cache, dict) else cache
                    cached_loras = raw_cached_loras
                    cached_loras, _hidden_schema_loras = self._filter_loras_for_active_family(cached_loras)
                    lora_options.extend([str(x) for x in cached_loras if str(x).strip()])
                    style_loras, _hidden_style_loras = self._filter_style_loras_for_active_family(raw_cached_loras)
                    style_lora_options.extend([str(x) for x in style_loras if str(x).strip()])
                except Exception as e:
                    logger.warning(f"[ComfyUI] 读取 LoRA 缓存用于更新 Schema 失败: {e}")

            lora_conf_for_schema = self.config.get("lora_settings", {}) if isinstance(self.config.get("lora_settings", {}), dict) else {}
            current_lora = lora_conf_for_schema.get("default_lora", "")
            invalid_current_lora = bool(current_lora and not self._is_lora_visible_for_family(current_lora))
            if current_lora and current_lora not in lora_options and self._is_lora_visible_for_family(current_lora):
                lora_options.append(current_lora)
            lora_options = list(dict.fromkeys(lora_options))
            current_style_lora = lora_conf_for_schema.get("default_style_lora", "")
            invalid_current_style_lora = bool(current_style_lora and not self._is_style_lora_visible_for_family(current_style_lora))
            if (
                current_style_lora
                and current_style_lora not in style_lora_options
                and self._is_style_lora_visible_for_family(current_style_lora)
            ):
                style_lora_options.append(current_style_lora)
            style_lora_options = list(dict.fromkeys(style_lora_options))

            lora_settings = data.setdefault('lora_settings', {
                "description": "LoRA 切换设置",
                "type": "object",
                "items": {}
            })
            lora_items = lora_settings.setdefault('items', {})
            if 'default_lora' in lora_items:
                lora_items['default_lora']['description'] = f"默认角色 LoRA（当前模型族：{self._family_label()}）"
                role_hint = (
                    "这里只切换角色 LoRA，只显示当前模型族兼容项；画风/质量 LoRA 不应放这里。"
                    "切换 /jh 模型 后刷新配置页即可看到对应模型族列表。"
                )
                if invalid_current_lora:
                    role_hint += f" 当前配置里的「{current_lora}」不属于 {self._family_label()}，生成时会被跳过；请清空或切回对应模型族。"
                lora_items['default_lora']['hint'] = role_hint
                lora_items['default_lora']['options'] = lora_options
                lora_items['default_lora']['enum'] = lora_options
            if 'default_style_lora' in lora_items:
                lora_items['default_style_lora']['description'] = f"默认画风 LoRA（当前模型族：{self._family_label()}）"
                style_hint = (
                    "只负责画风/质感 LoRA，不写角色档案。"
                    "留空时使用工作流里已有的固定画风节点；Illustrious 没有固定节点时留空就是不额外加画风 LoRA。"
                    "默认只显示未绑定角色档案、文件名能识别当前模型族且带 style/quality/aesthetic 等风格标记的 LoRA。"
                )
                if invalid_current_style_lora:
                    style_hint += f" 当前配置里的「{current_style_lora}」不像画风 LoRA 或与 {self._family_label()} 不兼容，生成时会被跳过。"
                lora_items['default_style_lora']['hint'] = style_hint
                lora_items['default_style_lora']['options'] = style_lora_options
                lora_items['default_style_lora']['enum'] = style_lora_options

            with open(schema_path, 'w', encoding='utf-8') as f:
                json.dump(data, f, indent=2, ensure_ascii=False)

            logger.info(
                f"[ComfyUI] 🔄 工作流列表已更新: {len(files)} 个 | "
                f"Checkpoint: {len(checkpoint_options)} 个 | "
                f"角色 LoRA: {max(len(lora_options)-1, 0)} 个 | 画风 LoRA: {max(len(style_lora_options)-1, 0)} 个"
            )

        except Exception as e:
            logger.error(f"[ComfyUI] 更新工作流/LoRA 列表失败: {e}")


    def _load_json_map_file(self, path: Path) -> dict:
        try:
            if path.exists():
                data = json.loads(path.read_text(encoding='utf-8'))
                if isinstance(data, dict):
                    return {str(k): str(v) for k, v in data.items() if str(k).strip() and str(v).strip()}
        except Exception as e:
            logger.warning(f"[ComfyUI] 读取映射文件失败 {path.name}: {e}")
        return {}

    def _save_json_map_file(self, path: Path, data: dict):
        path.write_text(json.dumps(data, ensure_ascii=False, indent=2), encoding='utf-8')

    def _normalize_model_family(self, value: str) -> str:
        family = self._parse_model_family(value)
        return family or MODEL_FAMILY_ANIMA

    def _parse_model_family(self, value: str):
        text = str(value or "").strip().lower()
        text = text.strip("|｜,，。;；:：")
        aliases = {
            "1": MODEL_FAMILY_ANIMA,
            "a": MODEL_FAMILY_ANIMA,
            "anima": MODEL_FAMILY_ANIMA,
            "2": MODEL_FAMILY_ILLUSTRIOUS,
            "i": MODEL_FAMILY_ILLUSTRIOUS,
            "ill": MODEL_FAMILY_ILLUSTRIOUS,
            "il": MODEL_FAMILY_ILLUSTRIOUS,
            "illustr": MODEL_FAMILY_ILLUSTRIOUS,
            "illustrious": MODEL_FAMILY_ILLUSTRIOUS,
            "illustriousxl": MODEL_FAMILY_ILLUSTRIOUS,
            "illustrious-xl": MODEL_FAMILY_ILLUSTRIOUS,
        }
        text = aliases.get(text, text)
        return text if text in SUPPORTED_MODEL_FAMILIES else None

    def _family_suffix(self, family: str = None) -> str:
        family = self._normalize_model_family(family or getattr(self, "active_model_family", MODEL_FAMILY_ANIMA))
        return "" if family == MODEL_FAMILY_ANIMA else f"_{family}"

    def _family_label(self, family: str = None) -> str:
        family = self._normalize_model_family(family or getattr(self, "active_model_family", MODEL_FAMILY_ANIMA))
        return "Illustrious" if family == MODEL_FAMILY_ILLUSTRIOUS else "Anima"

    def _style_preset_options(self) -> list:
        return list(ILLUSTRIOUS_STYLE_PRESETS.keys())

    def _style_preset_label(self, key: str = None) -> str:
        key = self._normalize_illustrious_style_preset(key)
        return str((ILLUSTRIOUS_STYLE_PRESETS.get(key) or {}).get("label") or key)

    def _normalize_illustrious_style_preset(self, value: str) -> str:
        text = str(value or "").strip()
        if not text:
            return ILLUSTRIOUS_STYLE_PRESET_DEFAULT
        numeric_aliases = {
            "1": ILLUSTRIOUS_STYLE_PRESET_DEFAULT,
            "2": ILLUSTRIOUS_STYLE_PRESET_PERFECT_REALISM,
            "3": ILLUSTRIOUS_STYLE_PRESET_PVC,
            "4": ILLUSTRIOUS_STYLE_PRESET_NEWPVC,
            "5": ILLUSTRIOUS_STYLE_PRESET_RANDOM,
        }
        if text in numeric_aliases:
            return numeric_aliases[text]
        lowered = text.lower().replace(" ", "").replace("_", "").replace("-", "")
        for key, preset in ILLUSTRIOUS_STYLE_PRESETS.items():
            aliases = [key, str(preset.get("label") or "")]
            aliases.extend([str(x) for x in (preset.get("aliases") or [])])
            for alias in aliases:
                marker = str(alias or "").strip().lower().replace(" ", "").replace("_", "").replace("-", "")
                if marker and lowered == marker:
                    return key
        return ILLUSTRIOUS_STYLE_PRESET_DEFAULT if lowered == "none" else ""

    def _configured_illustrious_style_preset(self) -> str:
        profile = self._model_family_config().get("illustrious", {})
        return self._normalize_illustrious_style_preset(profile.get("style_preset")) or ILLUSTRIOUS_STYLE_PRESET_DEFAULT

    def _configured_illustrious_checkpoint_name(self) -> str:
        profile = self._model_family_config().get("illustrious", {})
        return str(profile.get("checkpoint_name") or ILLUSTRIOUS_CHECKPOINT_NAME).replace("\\", "/").strip()

    def _normalize_checkpoint_key(self, value: str) -> str:
        text = str(value or "").strip().replace("\\", "/").split("/")[-1].lower()
        text = re.sub(r"\.(safetensors|ckpt|pt|pth)$", "", text, flags=re.I)
        return re.sub(r"[^0-9a-z]+", "", text)

    def _style_preset_key_for_checkpoint(self, checkpoint_name: str) -> str:
        marker = self._normalize_checkpoint_key(checkpoint_name)
        if not marker:
            return ""
        for key, preset in ILLUSTRIOUS_STYLE_PRESETS.items():
            if key in {ILLUSTRIOUS_STYLE_PRESET_DEFAULT, ILLUSTRIOUS_STYLE_PRESET_PVC, ILLUSTRIOUS_STYLE_PRESET_RANDOM}:
                continue
            preset_checkpoint = self._normalize_checkpoint_key(preset.get("checkpoint_name"))
            if preset_checkpoint and marker == preset_checkpoint:
                return key
        return ""

    def _apply_illustrious_style_preset_config(self, profile: dict, key: str) -> str:
        profile["style_preset"] = key
        reset_checkpoint = ""
        if key == ILLUSTRIOUS_STYLE_PRESET_DEFAULT:
            configured_checkpoint = str(profile.get("checkpoint_name") or "").strip()
            if self._style_preset_key_for_checkpoint(configured_checkpoint):
                reset_checkpoint = configured_checkpoint
                profile["checkpoint_name"] = ILLUSTRIOUS_CHECKPOINT_NAME
        self._illustrious_runtime_style_preset = ""
        self._illustrious_runtime_checkpoint_name = ""
        if getattr(self, "api", None) and hasattr(self.api, "runtime_checkpoint_name"):
            self.api.runtime_checkpoint_name = None
        return reset_checkpoint

    def _select_illustrious_runtime_style_preset(self, checkpoint_name: str = "") -> str:
        selected = self._resolve_illustrious_style_preset_for_generation(checkpoint_name=checkpoint_name)
        self._illustrious_runtime_style_preset = selected
        return selected

    def _resolve_illustrious_style_preset_for_generation(self, checkpoint_name: str = "") -> str:
        configured = self._configured_illustrious_style_preset()
        if configured == ILLUSTRIOUS_STYLE_PRESET_RANDOM:
            selected = random.choice(ILLUSTRIOUS_STYLE_PRESET_RANDOM_CHOICES)
        else:
            selected = configured
        if selected == ILLUSTRIOUS_STYLE_PRESET_DEFAULT:
            implied = self._style_preset_key_for_checkpoint(
                checkpoint_name
                or getattr(self, "_illustrious_runtime_checkpoint_name", "")
                or self._configured_illustrious_checkpoint_name()
            )
            if implied:
                selected = implied
        return selected

    def _active_illustrious_style_preset_key(self, style_preset_key: str = None, checkpoint_name: str = None) -> str:
        explicit = self._normalize_illustrious_style_preset(style_preset_key) if style_preset_key else ""
        if explicit:
            return explicit
        runtime = str(getattr(self, "_illustrious_runtime_style_preset", "") or "").strip()
        if runtime:
            return self._normalize_illustrious_style_preset(runtime) or ILLUSTRIOUS_STYLE_PRESET_DEFAULT
        configured = self._configured_illustrious_style_preset()
        if configured == ILLUSTRIOUS_STYLE_PRESET_DEFAULT:
            implied = self._style_preset_key_for_checkpoint(
                checkpoint_name
                or getattr(self, "_illustrious_runtime_checkpoint_name", "")
                or self._configured_illustrious_checkpoint_name()
            )
            if implied:
                return implied
        return configured

    def _active_illustrious_style_preset(self, style_preset_key: str = None, checkpoint_name: str = None) -> dict:
        key = self._active_illustrious_style_preset_key(style_preset_key=style_preset_key, checkpoint_name=checkpoint_name)
        preset = dict(ILLUSTRIOUS_STYLE_PRESETS.get(key) or ILLUSTRIOUS_STYLE_PRESETS[ILLUSTRIOUS_STYLE_PRESET_DEFAULT])
        preset["key"] = key
        return preset

    def _illustrious_dimension_value(self, value, default: int, min_value: int = 512, max_value: int = 4096) -> int:
        raw = int(round(_safe_float_value(value, default) or default))
        raw = max(min_value, min(raw, max_value))
        return max(min_value, min(int(round(raw / 64.0)) * 64, max_value))

    def _illustrious_oriented_size(
        self,
        width_value,
        height_value,
        default_width: int,
        default_height: int,
        aspect: str,
    ) -> tuple:
        width = self._illustrious_dimension_value(width_value, default_width)
        height = self._illustrious_dimension_value(height_value, default_height)
        aspect = str(aspect or "").strip().lower()
        if aspect == "portrait" and width >= height:
            return default_width, default_height
        if aspect in {"landscape", "wide"} and width <= height:
            return default_width, default_height
        return width, height

    def _illustrious_profile_number(self, profile: dict, key: str, default, min_value=None, max_value=None):
        value = _safe_float_value((profile or {}).get(key), default)
        if min_value is not None:
            value = max(float(min_value), value)
        if max_value is not None:
            value = min(float(max_value), value)
        if isinstance(default, int):
            return int(round(value))
        return round(float(value), 3)

    def _illustrious_default_generation_preset_from_config(self, preset: dict) -> dict:
        profile = self._current_family_profile(MODEL_FAMILY_ILLUSTRIOUS)
        result = dict(preset or {})
        result["sampler_name"] = str(profile.get("sampler") or result.get("sampler_name") or "euler_ancestral").strip()
        result["scheduler"] = str(profile.get("scheduler") or result.get("scheduler") or "normal").strip()
        result["steps"] = self._illustrious_profile_number(profile, "steps", ILLUSTRIOUS_DEFAULT_STEPS, 1, 80)
        result["cfg"] = self._illustrious_profile_number(profile, "cfg", ILLUSTRIOUS_DEFAULT_CFG, 1.0, 20.0)
        result["width"], result["height"] = self._illustrious_oriented_size(
            profile.get("width"),
            profile.get("height"),
            ILLUSTRIOUS_DEFAULT_WIDTH,
            ILLUSTRIOUS_DEFAULT_HEIGHT,
            "portrait",
        )
        result["refine_steps"] = self._illustrious_profile_number(profile, "refine_steps", ILLUSTRIOUS_DEFAULT_REFINE_STEPS, 0, 80)
        result["refine_cfg"] = self._illustrious_profile_number(profile, "refine_cfg", ILLUSTRIOUS_DEFAULT_REFINE_CFG, 1.0, 20.0)
        result["refine_denoise"] = self._illustrious_profile_number(profile, "refine_denoise", ILLUSTRIOUS_DEFAULT_REFINE_DENOISE, 0.0, 1.0)
        result["latent_upscale_by"] = self._illustrious_profile_number(profile, "latent_upscale_by", ILLUSTRIOUS_DEFAULT_LATENT_UPSCALE_BY, 1.0, 3.0)
        return result

    def _illustrious_generation_preset(self) -> dict:
        preset = self._active_illustrious_style_preset()
        if preset.get("key") == ILLUSTRIOUS_STYLE_PRESET_DEFAULT:
            preset = self._illustrious_default_generation_preset_from_config(preset)
        allowed = (
            "key", "label", "checkpoint_name", "sampler_name", "scheduler", "steps", "cfg",
            "refine_steps", "refine_cfg", "refine_denoise", "width", "height", "latent_upscale_by",
        )
        if preset.get("key") == ILLUSTRIOUS_STYLE_PRESET_DEFAULT:
            if self._configured_illustrious_style_preset() == ILLUSTRIOUS_STYLE_PRESET_RANDOM:
                return {"key": preset.get("key"), "label": preset.get("label")}
            return {key: preset.get(key) for key in allowed if key != "checkpoint_name" and preset.get(key) not in (None, "")}
        return {key: preset.get(key) for key in allowed if preset.get(key) not in (None, "")}

    def _illustrious_explicit_dimension_has_context(self, raw: str, match) -> bool:
        text = str(raw or "")
        if not text or not match:
            return False
        before = text[max(0, match.start() - 24):match.start()]
        after = text[match.end():match.end() + 24]
        nearby = f"{before} {after}".lower()
        if re.search(
            r"(尺寸|分辨率|解析度|画幅|画布|宽高|宽度|高度|像素|px|"
            r"横图|横屏|横版|横构图|横向构图|竖图|竖屏|竖版|竖构图|竖向构图|"
            r"宽屏|超宽屏|方图|正方形|"
            r"size|resolution|aspect|canvas|width|height|pixel|pixels|"
            r"landscape\s+(?:orientation|image|format|aspect|composition)|"
            r"horizontal\s+(?:orientation|image|format|composition)|"
            r"portrait|vertical\s+(?:image|orientation|format|composition)|"
            r"widescreen|ultra[-\s]*wide|ultrawide|square\s+(?:image|format|canvas))",
            nearby,
            re.I,
        ):
            return True
        bare = text.strip(" \t\r\n,，;；。.!！?？()[]{}")
        return bool(
            re.fullmatch(
                r"([5-9]\d{2}|[1-3]\d{3}|40\d{2})\s*[xX×＊*]\s*([5-9]\d{2}|[1-3]\d{3}|40\d{2})",
                bare,
            )
        )

    def _extract_illustrious_explicit_dimensions(self, text: str) -> tuple:
        raw = str(text or "")
        pattern = r"(?<!\d)([5-9]\d{2}|[1-3]\d{3}|40\d{2})\s*[xX×＊*]\s*([5-9]\d{2}|[1-3]\d{3}|40\d{2})(?!\d)"
        for match in re.finditer(pattern, raw):
            if not self._illustrious_explicit_dimension_has_context(raw, match):
                continue
            width = self._illustrious_dimension_value(match.group(1), ILLUSTRIOUS_DEFAULT_WIDTH)
            height = self._illustrious_dimension_value(match.group(2), ILLUSTRIOUS_DEFAULT_HEIGHT)
            return width, height
        return 0, 0

    def _illustrious_prompt_aspect_key(self, raw_prompt: str) -> str:
        text = str(raw_prompt or "").lower()
        if not text:
            return ""
        if re.search(r"(16\s*[:：]\s*9|21\s*[:：]\s*9|ultra[-\s]*wide|ultrawide|widescreen|宽屏|超宽屏|横幅|banner)", text, re.I):
            return "wide"
        if re.search(r"(1\s*[:：]\s*1|square\s+(?:image|format|canvas)|方图|正方形|方形|正方)", text, re.I):
            return "square"
        if re.search(
            r"(横图|横屏|横版|横构图|横向构图|横向|横着|横的|横幅|宽图|宽幅|宽一点|宽一些|更宽|landscape|wide\s+(?:shot|angle|image|format)|"
            r"horizontal)",
            text,
            re.I,
        ):
            return "landscape"
        if re.search(
            r"(竖图|竖屏|竖版|竖构图|竖向构图|竖向|竖着|竖的|立着|立绘|长图|高图|高一点|高一些|更高|窄一点|\bportrait\b|vertical|tall\s+(?:image|format))",
            text,
            re.I,
        ):
            return "portrait"
        return ""

    def _illustrious_size_for_aspect(self, aspect: str, profile: dict = None) -> tuple:
        profile = profile or self._current_family_profile(MODEL_FAMILY_ILLUSTRIOUS)
        aspect = str(aspect or "").strip().lower()
        if aspect == "wide":
            return self._illustrious_oriented_size(
                profile.get("wide_width"),
                profile.get("wide_height"),
                ILLUSTRIOUS_DEFAULT_WIDE_WIDTH,
                ILLUSTRIOUS_DEFAULT_WIDE_HEIGHT,
                "wide",
            )
        if aspect == "landscape":
            return self._illustrious_oriented_size(
                profile.get("landscape_width"),
                profile.get("landscape_height"),
                ILLUSTRIOUS_DEFAULT_LANDSCAPE_WIDTH,
                ILLUSTRIOUS_DEFAULT_LANDSCAPE_HEIGHT,
                "landscape",
            )
        if aspect == "square":
            size = self._illustrious_dimension_value(profile.get("square_size"), ILLUSTRIOUS_DEFAULT_SQUARE_SIZE)
            return size, size
        return self._illustrious_oriented_size(
            profile.get("width"),
            profile.get("height"),
            ILLUSTRIOUS_DEFAULT_WIDTH,
            ILLUSTRIOUS_DEFAULT_HEIGHT,
            "portrait",
        )

    def _illustrious_generation_request_dimensions(
        self,
        raw_prompt: str,
        img_width=None,
        img_height=None,
    ) -> dict:
        profile = self._current_family_profile(MODEL_FAMILY_ILLUSTRIOUS)
        explicit_width = self._illustrious_dimension_value(img_width, ILLUSTRIOUS_DEFAULT_WIDTH) if img_width not in (None, "", 0) else 0
        explicit_height = self._illustrious_dimension_value(img_height, ILLUSTRIOUS_DEFAULT_HEIGHT) if img_height not in (None, "", 0) else 0
        if explicit_width > 0 and explicit_height > 0:
            return {
                "width": explicit_width,
                "height": explicit_height,
                "aspect": "custom",
                "aspect_source": "args",
            }

        prompt_width, prompt_height = self._extract_illustrious_explicit_dimensions(raw_prompt)
        if prompt_width > 0 and prompt_height > 0:
            return {
                "width": prompt_width,
                "height": prompt_height,
                "aspect": "custom",
                "aspect_source": "prompt_size",
            }

        detected = ""
        if bool(profile.get("enable_prompt_aspect_detect", True)):
            detected = self._illustrious_prompt_aspect_key(raw_prompt)
        aspect = detected or "portrait"
        width, height = self._illustrious_size_for_aspect(aspect, profile)
        return {
            "width": width,
            "height": height,
            "aspect": aspect,
            "aspect_source": "prompt" if detected else "default",
        }

    def _apply_illustrious_generation_request_runtime(self, prepared: dict, source_image_path: str = None) -> dict:
        if source_image_path or not getattr(self, "api", None) or not hasattr(self.api, "runtime_generation_preset"):
            return {}
        prepared = prepared if isinstance(prepared, dict) else {}
        family = self._normalize_model_family(prepared.get("family") or self._configured_model_family())
        if family != MODEL_FAMILY_ILLUSTRIOUS:
            return {}
        size = self._illustrious_generation_request_dimensions(
            prepared.get("raw_prompt") or prepared.get("prompt") or "",
            img_width=prepared.get("img_width"),
            img_height=prepared.get("img_height"),
        )
        width = int(size.get("width") or 0)
        height = int(size.get("height") or 0)
        if width <= 0 or height <= 0:
            return {}
        current = dict(getattr(self.api, "runtime_generation_preset", None) or {})
        current["width"] = width
        current["height"] = height
        current["aspect"] = str(size.get("aspect") or "")
        current["aspect_source"] = str(size.get("aspect_source") or "")
        self.api.runtime_generation_preset = current
        profile_meta = prepared.get("profile_meta") if isinstance(prepared.get("profile_meta"), dict) else {}
        if isinstance(profile_meta, dict):
            profile_meta["illustrious_aspect"] = current["aspect"]
            profile_meta["illustrious_aspect_source"] = current["aspect_source"]
            profile_meta["illustrious_width"] = width
            profile_meta["illustrious_height"] = height
        logger.info(
            f"[ComfyUI] Illustrious 尺寸预设: {current['aspect'] or 'custom'} "
            f"{width}x{height} source={current['aspect_source'] or '-'}"
        )
        return current

    def _illustrious_lora_strength_cap(self) -> dict:
        preset = self._active_illustrious_style_preset()
        model_cap = preset.get("lora_strength_model_cap")
        clip_cap = preset.get("lora_strength_clip_cap")
        try:
            model_cap = float(model_cap)
        except Exception:
            model_cap = 0
        try:
            clip_cap = float(clip_cap)
        except Exception:
            clip_cap = 0
        if model_cap <= 0 and clip_cap <= 0:
            return {}
        return {
            "model": model_cap if model_cap > 0 else None,
            "clip": clip_cap if clip_cap > 0 else None,
            "reason": f"{preset.get('label') or '当前画风'}会限制角色 LoRA 强度，避免角色 LoRA 覆盖 checkpoint 画风",
        }

    def _load_model_family_state(self) -> dict:
        try:
            if self.model_family_state_path.exists():
                data = json.loads(self.model_family_state_path.read_text(encoding="utf-8"))
                if isinstance(data, dict):
                    return data
        except Exception as e:
            logger.warning(f"[ComfyUI] 读取模型族状态失败: {e}")
        return {}

    def _save_model_family_state(self):
        try:
            payload = {
                "active_family": getattr(self, "active_model_family", MODEL_FAMILY_ANIMA),
                "model_download": {
                    "checkpoint_dir": str(getattr(self, "model_download_checkpoint_dir", "") or ""),
                    "proxy": str(getattr(self, "model_download_proxy", "") or ""),
                    "timeout": int(getattr(self, "model_download_timeout", 3600) or 3600),
                },
                "updated_at": time.time(),
            }
            self.model_family_state_path.write_text(json.dumps(payload, ensure_ascii=False, indent=2), encoding="utf-8")
        except Exception as e:
            logger.warning(f"[ComfyUI] 保存模型族状态失败: {e}")

