    def _gpt_magic_comfy_editable_config(self) -> dict:
        return {
            "server_address": str(self.config.get("server_address", "") or ""),
            "workflow_settings": copy.deepcopy(self.config.get("workflow_settings", {}) or {}),
            "img2img_settings": copy.deepcopy(self.config.get("img2img_settings", {}) or {}),
            "avatar_redraw_settings": copy.deepcopy(self.config.get("avatar_redraw_settings", {}) or {}),
        }

    def _save_plugin_config_if_possible(self) -> None:
        try:
            if hasattr(self.config, "save_config"):
                self.config.save_config()
        except Exception as e:
            logger.warning(f"[ComfyUI] 保存插件配置失败: {e}")

    def _sync_editable_comfy_runtime_from_config(self) -> None:
        img2img_conf = self.config.get("img2img_settings", {}) or {}
        if not isinstance(img2img_conf, dict):
            img2img_conf = {}
        self.img2img_enabled = bool(img2img_conf.get("enable", True))
        self.img2img_character_replace_enabled = bool(img2img_conf.get("character_replace_enable", True))
        self.img2img_character_replace_denoise = min(
            max(_safe_float_value(img2img_conf.get("character_replace_denoise_strength", 1.0), 1.0), 0.01),
            1.0,
        )
        self.img2img_character_replace_lora_strength_model = min(
            max(_safe_float_value(img2img_conf.get("character_replace_lora_strength_model", 1.05), 1.05), 0.0),
            2.0,
        )
        self.img2img_character_replace_lora_strength_clip = min(
            max(_safe_float_value(img2img_conf.get("character_replace_lora_strength_clip", 1.0), 1.0), 0.0),
            2.0,
        )
        self.img2img_character_replace_control_strength = min(
            max(_safe_float_value(img2img_conf.get("character_replace_control_strength", 1.0), 1.0), 0.0),
            2.0,
        )
        self.img2img_character_replace_control_end = min(
            max(_safe_float_value(img2img_conf.get("character_replace_control_end_percent", 1.0), 1.0), 0.0),
            1.0,
        )
        self.img2img_character_replace_preprocessor_resolution = int(
            max(_safe_float_value(img2img_conf.get("character_replace_preprocessor_resolution", 1024), 1024), 256)
        )
        self.img2img_character_replace_scale_to_length = int(
            max(_safe_float_value(img2img_conf.get("character_replace_scale_to_length", 1536), 1536), 512)
        )
        self.img2img_character_replace_prompt = str(
            img2img_conf.get("character_replace_prompt", "")
            or DEFAULT_CHARACTER_REPLACE_PROMPT
        ).strip()
        self.img2img_character_replace_control_end = min(max(self.img2img_character_replace_control_end, 0.0), 1.0)

        avatar_redraw_conf = self.config.get("avatar_redraw_settings", {}) or {}
        if not isinstance(avatar_redraw_conf, dict):
            avatar_redraw_conf = {}
        self.avatar_redraw_enabled = bool(avatar_redraw_conf.get("enable", True))
        self.avatar_redraw_prompt = str(avatar_redraw_conf.get("prompt", "猪猪") or "猪猪").strip() or "猪猪"
        self.avatar_redraw_url_template = str(
            avatar_redraw_conf.get("avatar_url_template", "https://q1.qlogo.cn/g?b=qq&nk={qq}&s=640")
            or "https://q1.qlogo.cn/g?b=qq&nk={qq}&s=640"
        ).strip()
        self.avatar_redraw_timeout = max(
            int(_safe_float_value(avatar_redraw_conf.get("timeout", 20), 20)),
            3,
        )
        try:
            if self.api and hasattr(self.api, "_load_runtime_config"):
                self.api._load_runtime_config()
        except Exception as e:
            logger.debug(f"[ComfyUI] WebUI 保存后刷新 API 配置失败: {e}")

    def _apply_gpt_magic_comfy_settings(self, payload: dict) -> None:
        payload = payload or {}
        server_address = str(payload.get("server_address", "") or "").strip()
        if server_address:
            self.config["server_address"] = server_address

        workflow_patch = payload.get("workflow_settings")
        if isinstance(workflow_patch, dict):
            workflow_conf = self.config.setdefault("workflow_settings", {})
            if isinstance(workflow_conf, dict):
                for key in ("json_file", "input_node_id", "neg_node_id", "output_node_id"):
                    if key in workflow_patch:
                        workflow_conf[key] = str(workflow_patch.get(key) or "").strip()

        img2img_patch = payload.get("img2img_settings")
        if isinstance(img2img_patch, dict):
            img2img_conf = self.config.setdefault("img2img_settings", {})
            if isinstance(img2img_conf, dict):
                for key in (
                    "enable",
                    "auto_use_character_replace_workflow",
                    "character_replace_enable",
                ):
                    if key in img2img_patch:
                        img2img_conf[key] = bool(img2img_patch.get(key))
                for key in (
                    "character_replace_workflow",
                    "character_replace_input_node_id",
                    "character_replace_neg_node_id",
                    "character_replace_output_node_id",
                    "character_replace_lora_node_id",
                    "character_replace_preprocessor",
                    "upload_subfolder",
                ):
                    if key in img2img_patch:
                        img2img_conf[key] = str(img2img_patch.get(key) or "").strip()
                for key in (
                    "denoise_strength",
                    "character_replace_denoise_strength",
                    "character_replace_lora_strength_model",
                    "character_replace_lora_strength_clip",
                    "character_replace_control_strength",
                    "character_replace_control_end_percent",
                ):
                    if key in img2img_patch:
                        img2img_conf[key] = _safe_float_value(img2img_patch.get(key), _safe_float_value(img2img_conf.get(key), 1.0))
                for key in ("character_replace_preprocessor_resolution", "character_replace_scale_to_length"):
                    if key in img2img_patch:
                        img2img_conf[key] = int(_safe_float_value(img2img_patch.get(key), _safe_float_value(img2img_conf.get(key), 1024)))
                for key in ("character_replace_prompt", "negative_prompt"):
                    if key in img2img_patch:
                        img2img_conf[key] = str(img2img_patch.get(key) or "")

        avatar_patch = payload.get("avatar_redraw_settings")
        if isinstance(avatar_patch, dict):
            avatar_conf = self.config.setdefault("avatar_redraw_settings", {})
            if isinstance(avatar_conf, dict):
                if "enable" in avatar_patch:
                    avatar_conf["enable"] = bool(avatar_patch.get("enable"))
                for key in ("prompt", "avatar_url_template"):
                    if key in avatar_patch:
                        avatar_conf[key] = str(avatar_patch.get(key) or "").strip()
                if "timeout" in avatar_patch:
                    avatar_conf["timeout"] = int(_safe_float_value(avatar_patch.get("timeout"), 20))

        self._save_plugin_config_if_possible()
        self._sync_editable_comfy_runtime_from_config()

    def _build_gpt_magic_comfy_status(self) -> dict:
        status = {
            "插件版本": PLUGIN_VERSION,
            "ComfyUI 地址": str(self.config.get("server_address", "") or ""),
            "图生图": "开启" if self.img2img_enabled else "关闭",
            "自动撤回": f"{'开启' if self.auto_recall_generation_result else '关闭'} / {self.auto_recall_delay_seconds}秒",
            "Anima 图生图推荐": {
                "角色替换工作流": "character_replace_anima_reference_api.json",
                "denoise": "1.0",
                "LLLite strength": self.img2img_character_replace_control_strength,
                "LLLite end": self.img2img_character_replace_control_end,
                "预处理": "DepthAnythingV2Preprocessor @ 1024",
                "源图长边": self.img2img_character_replace_scale_to_length,
                "说明": "参考图只提供结构，目标角色由 LoRA 和提示词完整重画。",
            },
        }
        try:
            if self.api:
                self.api._load_runtime_config()
                loras = self.api.get_lora_cache() if hasattr(self.api, "get_lora_cache") else []
                status.update({
                    "当前工作流": getattr(self.api, "wf_filename", ""),
                    "正面节点": getattr(self.api, "input_id", ""),
                    "负面节点": getattr(self.api, "neg_node_id", ""),
                    "输出节点": getattr(self.api, "output_id", ""),
                    "当前 LoRA": getattr(self.api, "current_lora", "") or "未启用 / 工作流默认",
                    "LoRA 缓存数量": len(loras or []),
                })
        except Exception as e:
            status["ComfyUI 状态读取失败"] = str(e)
        status.update({
            "model_family": getattr(self, "active_model_family", MODEL_FAMILY_ANIMA),
            "model_family_label": self._family_label(),
            "lora_search_base_models": ", ".join(self._current_civitai_base_models()),
            "model_download": dict(getattr(self, "_model_download_status", {}) or {}),
            "editable_config": self._gpt_magic_comfy_editable_config(),
        })
        return status

