    def _paintable_role_page_size(self) -> int:
        return 96

    def _split_profile_list_values(self, value) -> list:
        if isinstance(value, str):
            return [item.strip() for item in re.split(r"[,，;；\n\r]+", value) if item.strip()]
        if isinstance(value, (list, tuple, set)):
            return [str(item).strip() for item in value if str(item or "").strip()]
        return []

    def _paintable_role_display_candidates(self, key: str, profile: dict) -> list:
        candidates = [profile.get("character") if isinstance(profile, dict) else "", key]
        if isinstance(profile, dict):
            for field in ("official_aliases", "aliases", "nickname_aliases", "search_aliases"):
                candidates.extend(self._split_profile_list_values(profile.get(field) or []))
            for evidence in profile.get("identity_evidence") or []:
                if isinstance(evidence, dict):
                    candidates.append(evidence.get("value"))
            source_title = str(profile.get("source_title") or "").strip()
            source_version_title = str(profile.get("source_version_title") or "").strip()
            candidates.extend(self._civitai_title_character_candidates(source_title))
            candidates.extend(self._civitai_title_character_candidates(source_version_title))
        return self._dedupe_profile_terms(
            [str(item or "").strip() for item in candidates if str(item or "").strip()],
            original_title=str((profile or {}).get("source_title") or "") if isinstance(profile, dict) else "",
        )

    def _paintable_role_cjk_display_name(self, key: str, profile: dict, fallback: str) -> str:
        for item in self._paintable_role_display_candidates(key, profile):
            marker = self._normalize_profile_match_key(item)
            if (
                item
                and re.search(r"[\u3400-\u9fff]", item)
                and 2 <= len(marker) <= 14
                and not self._is_generic_profile_match_term(item)
                and not self._is_lora_profile_bad_match_term(item)
            ):
                return str(item).strip()
        return str(fallback or key or "").strip()

    def _profile_alpha_sort_text(self, value: str) -> str:
        text = str(value or "").strip().replace("\\", "/").split("/")[-1]
        text = re.sub(r"\.(safetensors|ckpt|pt|bin)$", "", text, flags=re.I)
        return re.sub(r"[^0-9a-z]+", "", text.lower())

    def _lora_profile_alpha_sort_key(self, key: str, profile: dict) -> tuple:
        profile = profile if isinstance(profile, dict) else {}
        candidates = [profile.get("character")]
        for field in (
            "official_aliases",
            "aliases",
            "nickname_aliases",
            "search_aliases",
            "search_terms",
        ):
            candidates.extend(self._split_profile_list_values(profile.get(field) or []))
        candidates.extend(self._paintable_role_display_candidates(str(key or ""), profile))
        candidates.extend([
            profile.get("source_title"),
            profile.get("source_version_title"),
            Path(str(profile.get("lora") or "")).stem,
            key,
        ])
        for candidate in candidates:
            alpha = self._profile_alpha_sort_text(candidate)
            if alpha and not self._is_generic_profile_match_term(alpha):
                return (0, alpha[0], alpha, self._normalize_profile_match_key(profile.get("character") or key))
        fallback = self._normalize_profile_match_key(profile.get("character") or key)
        return (1, fallback[:1], fallback, str(key or "").lower())

    async def _fetch_paintable_role_live_loras(self) -> tuple:
        if not self.api:
            return [], "ComfyUI API 未初始化"
        try:
            loras, warn = await self.api.fetch_lora_list(force=True, allow_cache_fallback=False)
            loras = [str(x).strip() for x in (loras or []) if str(x).strip()]
            self._auto_update_schema()
            return loras, warn or ""
        except Exception as e:
            return [], str(e)

    def _build_paintable_role_rows(self, family: str = None, available_loras: list = None) -> tuple:
        family = self._normalize_model_family(family or getattr(self, "active_model_family", MODEL_FAMILY_ANIMA))
        profiles = self._get_lora_profiles(family)
        available_lora_keys = self._lora_key_set(available_loras) if available_loras is not None else None
        rows = []
        skipped = 0
        for key, profile in (profiles or {}).items():
            if not isinstance(profile, dict):
                skipped += 1
                continue
            conflict_reason = self._profile_identity_conflict_reason(str(key), profile)
            if conflict_reason:
                skipped += 1
                continue
            character = str(profile.get("character") or key or "").strip()
            if not character:
                skipped += 1
                continue
            lora_name = str(profile.get("lora") or "").strip()
            live_available = None
            if available_lora_keys is not None:
                lora_key = self._normalize_lora_lookup_key(lora_name)
                live_available = bool(lora_key and lora_key in available_lora_keys)
            display_name = self._paintable_role_cjk_display_name(str(key), profile, character)
            rows.append({
                "key": str(key),
                "family": family,
                "character": character,
                "display_name": display_name,
                "delete_target": str(key) or character or lora_name,
                "lora": Path(lora_name).name if lora_name else "",
                "live_available": live_available,
                "sort_key": self._lora_profile_alpha_sort_key(str(key), profile),
            })
        rows.sort(key=lambda row: (row.get("sort_key") or (1, "", "", ""), str(row.get("display_name") or "").lower()))
        for index, row in enumerate(rows, 1):
            row["index"] = index
        return rows, skipped

    def _paintable_role_page_from_text(self, rest: str, page_count: int = 1) -> int:
        text = str(rest or "").strip()
        page = 1
        if text:
            match = re.search(r"\d+", text)
            if match:
                try:
                    page = int(match.group(0))
                except Exception:
                    page = 1
        return max(1, min(page, max(int(page_count or 1), 1)))

    def _paintable_role_session_key(self, event: AstrMessageEvent) -> str:
        gid = self._get_group_id(event) if event else None
        scope = f"group:{gid}" if gid else "private"
        sender = str(event.get_sender_id() if event else "").strip() or "unknown"
        return f"{scope}:{sender}"

    def _cleanup_paintable_role_sessions(self):
        sessions = getattr(self, "_paintable_role_list_sessions", None)
        if not isinstance(sessions, dict):
            self._paintable_role_list_sessions = {}
            return
        now = time.time()
        for key, value in list(sessions.items()):
            if not isinstance(value, dict) or now - float(value.get("created_at") or 0) > 900:
                sessions.pop(key, None)

    def _remember_paintable_role_session(self, event: AstrMessageEvent, rows: list, family: str):
        self._cleanup_paintable_role_sessions()
        sessions = getattr(self, "_paintable_role_list_sessions", None)
        if not isinstance(sessions, dict):
            sessions = {}
            self._paintable_role_list_sessions = sessions
        compact_rows = []
        for row in rows or []:
            if not isinstance(row, dict):
                continue
            compact_rows.append({
                "index": int(row.get("index") or 0),
                "key": str(row.get("key") or ""),
                "family": str(row.get("family") or family or ""),
                "character": str(row.get("character") or ""),
                "display_name": str(row.get("display_name") or ""),
                "delete_target": str(row.get("delete_target") or row.get("key") or row.get("character") or ""),
                "lora": str(row.get("lora") or ""),
                "live_available": row.get("live_available"),
            })
        sessions[self._paintable_role_session_key(event)] = {
            "created_at": time.time(),
            "family": self._normalize_model_family(family),
            "rows": compact_rows,
        }

    def _resolve_paintable_role_delete_selector(self, event: AstrMessageEvent, selector: str, available_loras: list = None):
        text = str(selector or "").strip()
        if not text.isdigit():
            return None
        index = int(text)
        family = self._normalize_model_family(getattr(self, "active_model_family", MODEL_FAMILY_ANIMA))
        self._cleanup_paintable_role_sessions()
        session = (getattr(self, "_paintable_role_list_sessions", {}) or {}).get(self._paintable_role_session_key(event))
        if isinstance(session, dict) and session.get("family") == family:
            for row in session.get("rows") or []:
                if isinstance(row, dict) and int(row.get("index") or 0) == index:
                    return dict(row)
        rows, _skipped = self._build_paintable_role_rows(family=family, available_loras=available_loras)
        if 1 <= index <= len(rows):
            return dict(rows[index - 1])
        return None

