    def _write_paintable_roles_debug_html(self, html: str):
        try:
            path = self.data_dir / "paintable_roles_render.html"
            path.write_text(str(html or ""), encoding="utf-8")
        except Exception as e:
            logger.debug(f"[ComfyUI] 写入角色列表调试 HTML 失败: {e}")

    def _normalize_paintable_roles_render(self, path: str) -> tuple:
        try:
            from PIL import Image as PILImage, ImageOps
        except Exception as e:
            return "", f"缺少 Pillow，无法规范化角色列表图：{e}"
        try:
            src = Path(str(path or ""))
            if not src.exists():
                return "", f"角色列表渲染图不存在：{path}"
            with PILImage.open(src) as img:
                img = ImageOps.exif_transpose(img)
                if img.mode in {"RGBA", "LA"} or (img.mode == "P" and "transparency" in img.info):
                    rgba = img.convert("RGBA")
                    base = PILImage.new("RGB", rgba.size, (255, 255, 255))
                    base.paste(rgba, mask=rgba.getchannel("A"))
                    img = base
                else:
                    img = img.convert("RGB")
                max_width = 1080
                max_height = 3200
                scale = min(max_width / max(img.width, 1), max_height / max(img.height, 1), 1.0)
                if scale < 1.0:
                    resample = getattr(getattr(PILImage, "Resampling", PILImage), "LANCZOS", 1)
                    img = img.resize((max(int(img.width * scale), 1), max(int(img.height * scale), 1)), resample)
                out_path = self.data_dir / "paintable_roles_send.jpg"
                quality = 91
                while True:
                    img.save(out_path, format="JPEG", quality=quality, optimize=True, progressive=False)
                    size = out_path.stat().st_size
                    if size <= 1600 * 1024 or quality <= 72:
                        break
                    quality -= 6
                logger.info(f"[ComfyUI] 角色列表图已规范化: {img.width}x{img.height} {out_path.stat().st_size}B q={quality}")
                return str(out_path), ""
        except Exception as e:
            src = Path(str(path or ""))
            return "", f"角色列表图规范化失败：{self._short_user_error(e)}{self._self_update_render_file_head(src)}"

    async def _render_paintable_roles_image_local(self, rows: list, page: int, page_count: int, total: int, skipped: int, family_label: str, unavailable: int = 0) -> tuple:
        self._apply_self_update_render_env()
        ok, error = await self._ensure_self_update_playwright_package()
        if not ok:
            return "", error
        try:
            from playwright.async_api import async_playwright
        except Exception as e:
            return "", f"playwright 导入失败：{self._short_user_error(e, 260)}"
        rendered_html = self._compose_paintable_roles_html(rows, page, page_count, total, skipped, family_label, unavailable=unavailable)
        self._write_paintable_roles_debug_html(rendered_html)
        out_path = self.data_dir / "paintable_roles_local_render.jpg"
        last_error = ""
        installed_browser = False
        installed_deps = False
        for _attempt in range(4):
            browser = None
            try:
                async with async_playwright() as p:
                    browser_type_name = self._self_update_render_browser_name()
                    browser_type = getattr(p, browser_type_name)
                    launch_args = []
                    if browser_type_name == "chromium":
                        launch_args = [
                            "--no-sandbox",
                            "--disable-setuid-sandbox",
                            "--disable-dev-shm-usage",
                            "--disable-gpu",
                            "--font-render-hinting=medium",
                        ]
                    browser = await browser_type.launch(headless=True, args=launch_args)
                    page_obj = await browser.new_page(
                        viewport={"width": 1180, "height": 1500},
                        device_scale_factor=1,
                    )
                    await page_obj.emulate_media(media="screen")
                    await page_obj.set_content(rendered_html, wait_until="load", timeout=45000)
                    try:
                        await page_obj.evaluate("() => document.fonts && document.fonts.ready")
                    except Exception:
                        pass
                    await page_obj.wait_for_timeout(120)
                    await page_obj.screenshot(
                        path=str(out_path),
                        type="jpeg",
                        quality=92,
                        full_page=True,
                        animations="disabled",
                    )
                    await browser.close()
                    browser = None
                normalized_path, normalize_error = self._normalize_paintable_roles_render(str(out_path))
                if normalized_path:
                    return normalized_path, ""
                return "", normalize_error
            except Exception as e:
                last_error = self._short_user_error(e, 900)
                try:
                    if browser:
                        await browser.close()
                except Exception:
                    pass
                if self._self_update_playwright_needs_browser_install(e) and not installed_browser:
                    installed, install_error = await self._install_self_update_playwright_browser()
                    if installed:
                        installed_browser = True
                        continue
                    last_error = install_error
                if self._self_update_playwright_needs_deps_install(e) and not installed_deps:
                    installed, install_error = await self._install_self_update_playwright_deps()
                    if installed:
                        installed_deps = True
                        continue
                    last_error = install_error
                break
        return "", f"本地浏览器渲染角色列表失败：{last_error}"

    def _build_paintable_roles_text(self, rows: list = None, page: int = 1, page_count: int = 1, total: int = None, skipped: int = 0, error: str = "", unavailable: int = 0) -> str:
        family_label = self._family_label()
        if rows is None:
            all_rows, skipped = self._build_paintable_role_rows()
            page_size = self._paintable_role_page_size()
            total = len(all_rows)
            page_count = max(1, math.ceil(total / page_size)) if total else 1
            page = self._paintable_role_page_from_text(str(page), page_count=page_count)
            start = (page - 1) * page_size
            rows = all_rows[start:start + page_size]
        total = int(total if total is not None else len(rows or []))
        if not rows:
            suffix = f"\n已跳过 {skipped} 个不可用或禁用档案。" if skipped else ""
            return (
                f"🎭 可以画的角色（{family_label}）\n"
                "━━━━━━━━━━━━━━━━━━\n"
                f"当前模型族没有可直接匹配的角色档案。{suffix}"
            )
        lines = [f"🎭 可以画的角色（{family_label}） 第 {page}/{page_count} 页", "━━━━━━━━━━━━━━━━━━"]
        cells = []
        for row in rows:
            name = str(row.get("display_name") or row.get("character") or row.get("key") or "-").strip()
            if len(name) > 12:
                name = name[:11] + "…"
            cells.append(f"{int(row.get('index') or 0):03d} {name}")
        for idx in range(0, len(cells), 3):
            lines.append("  ".join(f"{cell:<18}" for cell in cells[idx:idx + 3]).rstrip())
        lines.append("━━━━━━━━━━━━━━━━━━")
        lines.append(f"共 {total} 个角色；删除：/jh 删除角色 <序号>；翻页：/jh 角色列表 {min(page + 1, page_count)}")
        if skipped:
            lines.append(f"已隐藏 {skipped} 个禁用或身份冲突档案。")
        if unavailable:
            lines.append(f"实时未匹配 {unavailable} 个 LoRA，已保留显示；切回对应 ComfyUI/LoRA 目录后可直接恢复。")
        if error:
            lines.append(f"图片渲染失败：{error}")
        return "\n".join(lines)

    async def _handle_paintable_roles_command(self, event: AstrMessageEvent, rest: str = ""):
        family = self._normalize_model_family(getattr(self, "active_model_family", MODEL_FAMILY_ANIMA))
        family_label = self._family_label(family)
        available_loras, live_warn = await self._fetch_paintable_role_live_loras()
        if live_warn:
            logger.warning(f"[ComfyUI] 角色列表刷新实时 LoRA 提示: {live_warn}")
        rows, skipped = self._build_paintable_role_rows(family=family, available_loras=available_loras)
        unavailable = sum(1 for row in rows if isinstance(row, dict) and row.get("live_available") is False) if available_loras else 0
        if not rows:
            suffix = f"\n已跳过 {skipped} 个不可用或禁用档案。" if skipped else ""
            yield event.plain_result(
                f"🎭 可以画的角色（{family_label}）\n"
                "━━━━━━━━━━━━━━━━━━\n"
                f"当前模型族没有可直接匹配的角色档案。{suffix}\n"
                "先用 /jh 找lora <角色名> 搜索并导入。"
            )
            return
        page_size = self._paintable_role_page_size()
        total = len(rows)
        page_count = max(1, math.ceil(total / page_size))
        page = self._paintable_role_page_from_text(rest, page_count=page_count)
        start = (page - 1) * page_size
        page_rows = rows[start:start + page_size]
        self._remember_paintable_role_session(event, rows, family)
        path, error = await self._render_paintable_roles_image_local(page_rows, page, page_count, total, skipped, family_label, unavailable=unavailable)
        if path:
            yield event.chain_result([Image.fromFileSystem(path)])
            return
        yield event.plain_result(
            self._build_paintable_roles_text(
                rows=page_rows,
                page=page,
                page_count=page_count,
                total=total,
                skipped=skipped,
                unavailable=unavailable,
                error=error,
            )
        )

    def _build_jh_help_result(self, event: AstrMessageEvent, is_admin: bool = False, is_super_admin: bool = False):
        text = self._build_jh_help_text(is_admin=is_admin, is_super_admin=is_super_admin)
        return event.chain_result([
            Node(
                uin=self._safe_self_id_int(event),
                name="酒狐帮助",
                content=[Plain(text)],
            )
        ])

