    # ====== 权限检查（返回原因）======
    def _check_access(self, event: AstrMessageEvent) -> tuple:
        """
        统一的权限检查，返回 (是否通过, 拒绝原因)
        """
        user_id = str(event.get_sender_id())
        is_admin = user_id in self.admin_user_ids
        
        # 1. 全局锁定检查
        if self.lockdown and not is_admin:
            return False, "🔒 绘图失败:绘图功能锁定中，仅超级管理员可用"
        
        # 2. 群聊白名单检查
        if self._is_group_message(event):
            gid = self._get_group_id(event)
            if not gid:
                return False, "⚠️ 无法获取群号"
            
            # 白名单为空表示不限制群；配置了群号时才拦截未授权群。
            if self.whitelist_group_ids and gid not in self.whitelist_group_ids:
                # 管理员可以绕过
                if is_admin and self.admin_bypass_whitelist:
                    pass  # 放行
                else:
                    return False, f"🚫 本群({gid})不在白名单中"
        
        return True, ""

    def _is_special_whitelist_group(self, event: AstrMessageEvent) -> bool:
        if not getattr(self, "special_whitelist_enabled", True):
            return False
        if not self._is_group_message(event):
            return False
        gid = self._get_group_id(event)
        return bool(gid and gid in getattr(self, "special_whitelist_group_ids", set()))

    def _bypass_generation_controls(self, event: AstrMessageEvent) -> bool:
        return self._is_special_whitelist_group(event)

    def _check_generation_access(self, event: AstrMessageEvent) -> tuple:
        if self._bypass_generation_controls(event):
            return True, ""
        return self._check_access(event)

    def _check_cooldown(self, event: AstrMessageEvent) -> tuple:
        """
        冷却检查，返回 (是否通过, 剩余秒数或0)
        """
        if self._bypass_generation_controls(event):
            return True, 0
        user_id = str(event.get_sender_id())
        is_admin = user_id in self.admin_user_ids
        
        # 管理员绕过冷却
        if is_admin and self.admin_bypass_cooldown:
            return True, 0
        
        current_time = time.time()
        last_time = self.user_cooldowns.get(user_id, 0)
        elapsed = current_time - last_time

        if elapsed < self.cooldown_seconds:
            remain = int(self.cooldown_seconds - elapsed)
            return False, remain

        self.user_cooldowns[user_id] = current_time
        return True, 0

    def _check_sensitive(self, prompt: str, event: AstrMessageEvent) -> tuple:
        """
        敏感词检查，返回 (是否通过, 触发的敏感词列表)
        """
        if self._bypass_generation_controls(event):
            return True, []
        user_id = str(event.get_sender_id())
        is_admin = user_id in self.admin_user_ids
        
        sensitive = self._find_sensitive_words(prompt, event)
        
        if not sensitive:
            return True, []
        
        # 管理员绕过
        if is_admin and self.admin_bypass_sensitive:
            logger.info(f"[ComfyUI] 👑 管理员 {user_id} 使用敏感词 {sensitive}，已放行")
            return True, []
        
        return False, sensitive

    def _main_llm_system_injection_text(self) -> str:
        if not getattr(self, "enable_system_prompt_injection", True):
            return ""
        text = str(getattr(self, "main_llm_system_prompt", "") or "").strip()
        if text:
            return text
        try:
            llm_settings = self.config.get("llm_settings", {}) if isinstance(self.config, dict) else {}
            return str(llm_settings.get("system_prompt", "") or "").strip()
        except Exception:
            return ""

    def _append_text_attr_once(self, obj, attr: str, text: str) -> bool:
        text = str(text or "").strip()
        if not text or not hasattr(obj, attr):
            return False
        current = str(getattr(obj, attr, "") or "")
        if text in current:
            return False
        updated = (current.rstrip() + "\n\n" + text).strip() if current.strip() else text
        try:
            setattr(obj, attr, updated)
            return True
        except Exception:
            return False

    def _inject_main_llm_messages(self, req, text: str) -> bool:
        text = str(text or "").strip()
        if not text:
            return False
        changed = False
        for attr in ("messages", "message", "prompt_messages"):
            messages = getattr(req, attr, None)
            if not isinstance(messages, list):
                continue
            updated = self._append_llm_system_text(messages, text)
            if updated is not messages:
                try:
                    setattr(req, attr, updated)
                except Exception:
                    pass
            changed = True
        return changed

    def _inject_main_llm_system_prompt(self, req, text: str) -> bool:
        text = str(text or "").strip()
        if not text:
            return False
        changed = False
        for attr in ("system_prompt", "system", "instruction"):
            changed = self._append_text_attr_once(req, attr, text) or changed
        changed = self._inject_main_llm_messages(req, text) or changed
        if getattr(self, "mirror_llm_injection_to_user", True):
            for attr in ("prompt", "user_prompt"):
                changed = self._append_text_attr_once(req, attr, f"System instructions:\n{text}") or changed
        return changed

    @filter.on_llm_request(priority=100)
    async def inject_system_prompt(self, event: AstrMessageEvent, req):
        """注入系统提示词 + 清理历史中的绘图提示词"""
        raw_message = str(getattr(event, "message_str", "") or "").strip()
        trigger_candidates = self._event_plain_text_candidates(event) or [raw_message]
        self_update_raw = next((text for text in trigger_candidates if self._is_self_update_trigger(text, event=event)), "")
        if self_update_raw and not event.get_extra("comfy_self_update_handled"):
            try:
                event.set_extra("comfy_self_update_handled", True)
                event.should_call_llm(True)
                event.stop_event()
                if hasattr(req, "prompt"):
                    req.prompt = ""
            except Exception:
                pass
            logger.info(f"[ComfyUI] 在 LLM 请求阶段接管酒狐更新画图，text={self_update_raw[:24]}")
            async for result in self._handle_self_update_command(event, self_update_raw):
                await self._send_result_safely(event, result, context="self_update_llm_request")
            return
        if (
            any(self._is_plain_paint_trigger(text, event=event) for text in trigger_candidates)
            or any(self._is_plain_video_trigger(text, event=event) for text in trigger_candidates)
            or any(self._is_gpt_magic_trigger(text) for text in trigger_candidates)
            or any(self._is_image_audit_trigger(text, event=event) for text in trigger_candidates)
            or any(self._is_look_trigger(text, event=event) for text in trigger_candidates)
            or any(self._is_generation_stats_trigger(text, event=event) for text in trigger_candidates)
            or any(self._is_prompt_note_trigger(text, event=event) for text in trigger_candidates)
            or any(self._is_prompt_notebook_trigger(text, event=event) for text in trigger_candidates)
            or any(self._is_gallery_register_trigger(text, event=event) for text in trigger_candidates)
            or self._has_prompt_note_pending(event)
            or any(self._is_delegate_magic_trigger(text, event=event) for text in trigger_candidates)
            or any(self._is_test_mode_trigger(text, event=event) or ((self._parse_jh_command_text(text) or {}).get("action") == "test_mode") for text in trigger_candidates)
        ):
            try:
                event.should_call_llm(True)
                event.stop_event()
                if hasattr(req, "prompt"):
                    req.prompt = ""
            except Exception:
                pass
            return

        try:
            my_prompt = self._main_llm_system_injection_text()
            if my_prompt and self._inject_main_llm_system_prompt(req, my_prompt):
                logger.debug(f"[ComfyUI] 主 LLM 系统提示词已注入 chars={len(my_prompt)}")

            draw_tool_block = self._build_llm_draw_tool_prompt_block()
            current_prompt = getattr(req, "system_prompt", "") or ""
            if draw_tool_block and "【酒狐绘图函数】" not in current_prompt:
                self._inject_main_llm_system_prompt(req, draw_tool_block)
            if self._ensure_llm_draw_tool_in_request(req):
                logger.debug("[ComfyUI] 本轮 LLM 请求已注入 jiuhu_draw_image 工具")

            lora_block = self._build_lora_profiles_prompt_block()
            if lora_block:
                current_prompt = getattr(req, "system_prompt", "") or ""
                if "【已安装可自动调用的 LoRA 角色库】" not in current_prompt:
                    self._inject_main_llm_system_prompt(req, lora_block)

        except Exception as e:
            logger.error(f"[ComfyUI] 注入提示词异常: {e}")

        # 清理历史中的绘图提示词
        if self.discard_prompt_from_history:
            try:
                self._clean_pic_tags_from_req(req)
            except Exception as e:
                logger.error(f"[ComfyUI] 清理提示词异常: {e}")

    def _clean_pic_tags_from_req(self, req):
        """从请求的 conversation.history 中清理 <pic> 标签"""
        pic_pattern = re.compile(r'<pic\s+prompt=".*?">', re.DOTALL)

        conversation = getattr(req, "conversation", None)
        if conversation is None:
            logger.warning("[ComfyUI] 🗑️ req.conversation 不存在，跳过清理")
            return

        history_raw = getattr(conversation, "history", None)
        if not history_raw:
            return

        try:
            history = json.loads(history_raw) if isinstance(history_raw, str) else history_raw
        except (json.JSONDecodeError, TypeError):
            return

        if not isinstance(history, list):
            return

        cleaned = 0
        for entry in history:
            if not isinstance(entry, dict):
                continue
            if entry.get("role") != "assistant":
                continue
            content = entry.get("content", "")
            if isinstance(content, str) and pic_pattern.search(content):
                entry["content"] = pic_pattern.sub("", content).strip()
                cleaned += 1

        if cleaned:
            # 写回 conversation.history
            conversation.history = json.dumps(history, ensure_ascii=False)
            logger.info(f"[ComfyUI] 🗑️ 已从 conversation.history 中清理 {cleaned} 条消息的绘图提示词")

    def _plain_paint_keywords(self) -> list:
        return ["酒狐来点"]

    def _plain_local_video_keywords(self) -> list:
        return ["酒狐来点视频"]

    def _plain_api_video_keywords(self) -> list:
        # Grok API 视频触发词，必须比本地短词 "酒狐来点视频" 优先匹配
        return ["酒狐来点魔法视频", "酒狐来点视频魔法"]

    def _plain_video_keywords(self) -> list:
        # 所有视频触发词（API 在前），用于画图触发互斥判断
        return self._plain_api_video_keywords() + self._plain_local_video_keywords()

    def _clean_prompt_after_trigger(self, text: str) -> str:
        return re.sub(r'^[\s+＋:：，,、]+', '', str(text or '')).strip()

    def _is_wake_stripped_paint_trigger(self, raw: str, event: AstrMessageEvent = None) -> bool:
        return False

    def _is_plain_paint_trigger(self, raw: str, event: AstrMessageEvent = None) -> bool:
        raw = str(raw or '').strip()
        if not raw or raw.startswith('/'):
            return False
        if self._is_plain_video_trigger(raw, event=event):
            return False
        lower_raw = raw.lower()
        for keyword in self._plain_paint_keywords():
            if lower_raw.startswith(str(keyword).lower()):
                return True
        return False

    def _extract_plain_paint_prompt(self, raw: str, event: AstrMessageEvent = None):
        raw = str(raw or '').strip()
        if not raw or raw.startswith('/'):
            return None
        if self._is_plain_video_trigger(raw, event=event):
            return None
        lower_raw = raw.lower()
        for keyword in self._plain_paint_keywords():
            key = str(keyword)
            if lower_raw.startswith(key.lower()):
                return self._clean_prompt_after_trigger(raw[len(key):])
        return None

    def _is_plain_video_trigger(self, raw: str, event: AstrMessageEvent = None) -> bool:
        raw = str(raw or '').strip()
        if not raw or raw.startswith('/'):
            return False
        lower_raw = raw.lower()
        for keyword in self._plain_video_keywords():
            if lower_raw.startswith(str(keyword).lower()):
                return True
        return False

    def _extract_plain_video_prompt(self, raw: str, event: AstrMessageEvent = None):
        prompt, _mode = self._extract_plain_video_request(raw, event=event)
        return prompt

    def _extract_plain_video_request(self, raw: str, event: AstrMessageEvent = None):
        """返回 (提示词, 模式)。模式为 'api'(Grok) 或 'local'(Wan)，未命中返回 (None, '')。
        API 长触发词优先于本地短触发词，避免 "酒狐来点视频魔法" 被本地视频抢匹配。"""
        raw = str(raw or '').strip()
        if not raw or raw.startswith('/'):
            return None, ""
        lower_raw = raw.lower()
        for keyword in self._plain_api_video_keywords():
            key = str(keyword)
            if lower_raw.startswith(key.lower()):
                return self._clean_prompt_after_trigger(raw[len(key):]), "api"
        for keyword in self._plain_local_video_keywords():
            key = str(keyword)
            if lower_raw.startswith(key.lower()):
                return self._clean_prompt_after_trigger(raw[len(key):]), "local"
        return None, ""

    def _is_gpt_magic_trigger(self, raw: str) -> bool:
        raw = str(raw or "").strip()
        if not raw:
            return False
        clean = raw[1:].strip() if raw.startswith("/") else raw
        lower = clean.lower()
        return (
            clean.startswith("酒狐魔法")
            or lower.startswith("jh magic")
            or lower.startswith("jhmagic")
            or lower.startswith("jhm")
        )

    def _gallery_register_command_body(self, raw: str) -> str:
        clean = self._plain_trigger_text(raw)
        if clean.startswith("/"):
            clean = clean[1:].strip()
        if re.fullmatch(r"WFREG-[A-Za-z0-9_-]+", clean):
            return clean
        if clean.startswith("酒狐魔法"):
            return ""
        if clean.startswith("酒狐注册"):
            body = clean[len("酒狐注册"):].strip()
            return body[1:].strip() if body.startswith(("+", "＋")) else body
        return ""

    def _is_gallery_register_trigger(self, raw: str, event: AstrMessageEvent = None) -> bool:
        clean = self._plain_trigger_text(raw)
        if not clean or clean.startswith("/"):
            return False
        return clean.startswith("酒狐注册") and not clean.startswith("酒狐魔法")

    def _plain_trigger_text(self, raw: str) -> str:
        text = str(raw or "").strip()
        text = re.sub(r"[\u061c\u200b-\u200f\u202a-\u202e\u2060-\u206f\ufeff]", "", text).strip()
        text = re.sub(r"\[CQ:reply[^\]]*\]", "", text, flags=re.IGNORECASE).strip()
        text = re.sub(r"^(?:\[(?:引用消息|回复消息|reply|Reply)\]\s*)+", "", text).strip()
        text = re.sub(r"\[CQ:image[^\]]*\]", "", text, flags=re.IGNORECASE).strip()
        text = re.sub(r"\[(?:图片|image)\]", "", text, flags=re.IGNORECASE).strip()
        return text

    def _is_wake_event(self, event: AstrMessageEvent = None) -> bool:
        if event is None:
            return False
        return bool(
            getattr(event, "is_wake", False)
            or getattr(event, "is_at_or_wake_command", False)
            or (hasattr(event, "is_wake_up") and event.is_wake_up())
        )

    def _is_image_audit_tail(self, tail: str) -> bool:
        if not tail:
            return True
        if tail[:1].isspace():
            return True
        compact = (
            "初始化", "状态", "查看", "进度", "帮助", "部署", "下载", "下载模型", "模型", "准备",
            "init", "status", "show", "progress", "help", "deploy",
        )
        clean = str(tail or "").strip().lower()
        return any(clean == item or clean.startswith(item + " ") for item in compact)

    def _starts_image_audit_command(self, clean: str, heads) -> bool:
        clean = str(clean or "").strip()
        for head in heads:
            if clean.startswith(head) and self._is_image_audit_tail(clean[len(head):]):
                return True
        return False

    def _is_wake_stripped_image_audit_trigger(self, clean: str, event: AstrMessageEvent = None) -> bool:
        return False

    def _extract_plain_text_from_component(self, comp) -> str:
        if comp is None:
            return ""
        reply_cls = globals().get("Reply")
        if reply_cls is not None:
            try:
                if isinstance(comp, reply_cls):
                    return ""
            except Exception:
                pass
        if isinstance(comp, str):
            return comp
        if isinstance(comp, dict):
            if comp.get("type") == "text":
                data = comp.get("data", {}) or {}
                return str(data.get("text") or data.get("content") or "")
            return ""
        for attr in ("text", "content", "message"):
            value = getattr(comp, attr, None)
            if isinstance(value, str) and value.strip():
                return value
        data = getattr(comp, "data", None)
        if isinstance(data, dict):
            return str(data.get("text") or data.get("content") or "")
        return ""

    def _event_plain_text_candidates(self, event: AstrMessageEvent) -> list:
        values = []

        def add(value):
            text = self._plain_trigger_text(value)
            if text and text not in values:
                values.append(text)

        add(getattr(event, "message_str", ""))
        msg_obj = getattr(event, "message_obj", None)
        if msg_obj is not None:
            add(getattr(msg_obj, "raw_message", ""))
            add(getattr(msg_obj, "message_str", ""))
            for comp in (getattr(msg_obj, "message", None) or []):
                add(self._extract_plain_text_from_component(comp))
            raw_obj = getattr(msg_obj, "raw", None)
            if isinstance(raw_obj, dict):
                add(raw_obj.get("raw_message", ""))
                for seg in (raw_obj.get("message", []) or []):
                    add(self._extract_plain_text_from_component(seg))
                for elem in (raw_obj.get("elements", []) or []):
                    if not isinstance(elem, dict):
                        continue
                    text_elem = elem.get("textElement") or {}
                    if isinstance(text_elem, dict):
                        add(text_elem.get("content", ""))
        try:
            for comp in event.get_messages() or []:
                add(self._extract_plain_text_from_component(comp))
        except Exception:
            pass
        return values

    def _is_image_audit_trigger(self, raw: str, event: AstrMessageEvent = None) -> bool:
        clean = self._plain_trigger_text(raw)
        if not clean or clean.startswith("/"):
            return False
        lower = clean.lower()
        prefix = str(getattr(self, "command_prefix", "jh") or "jh").strip() or "jh"
        lower_prefix = prefix.lower()
        if self._starts_image_audit_command(clean, ("酒狐审核", "酒狐鉴黄")):
            return True
        if self._starts_image_audit_command(
            lower,
            (
                f"{lower_prefix}图片审核",
                f"{lower_prefix}鉴黄",
                f"{lower_prefix} 图片审核",
                f"{lower_prefix} 鉴黄",
            ),
        ):
            return True
        return False

    def _is_self_update_tail(self, tail: str) -> bool:
        if not tail:
            return True
        clean = str(tail or "").strip().lower()
        if not clean:
            return True
        if re.fullmatch(r"v?\d+(?:\.\d+){1,5}(?:[-+][0-9A-Za-z][0-9A-Za-z_.-]*)?", clean, re.I):
            return True
        if re.match(r"^(强制更新|强制|force[-_ ]?update|force)\s*v?\d+(?:\.\d+){1,5}", clean, re.I):
            return True
        allowed = ("状态", "记录", "历史", "帮助", "检查", "强制", "强制更新", "force", "force-update", "force_update", "status", "check", "log", "logs", "history", "help")
        return any(clean == item or clean.startswith(item + " ") for item in allowed)

    def _starts_self_update_command(self, clean: str, heads) -> bool:
        clean = str(clean or "").strip()
        for head in heads:
            if clean.startswith(head) and self._is_self_update_tail(clean[len(head):]):
                return True
        return False

    def _is_self_update_trigger(self, raw: str, event: AstrMessageEvent = None) -> bool:
        clean = self._plain_trigger_text(raw)
        if not clean or clean.startswith("/"):
            return False
        lower = clean.lower()
        prefix = str(getattr(self, "command_prefix", "jh") or "jh").strip() or "jh"
        lower_prefix = prefix.lower()
        if self._starts_self_update_command(clean, ("酒狐强制更新", "酒狐画图强制更新", "酒狐更新画图", "酒狐画图更新")):
            return True
        return self._starts_self_update_command(
            lower,
            (
                f"{lower_prefix}强制更新",
                f"{lower_prefix} 强制更新",
                f"{lower_prefix}更新画图",
                f"{lower_prefix} 更新画图",
                "jh强制更新",
                "jh 强制更新",
                "jh更新画图",
                "jh 更新画图",
            ),
        )

    def _is_wake_stripped_gpt_magic_trigger(self, clean: str) -> bool:
        clean = str(clean or "").strip()
        if not clean.startswith("魔法"):
            return False
        rest = clean[len("魔法"):]
        if not rest:
            return True
        if rest[:1].isspace() or rest.startswith(("+", "＋")):
            return True
        command_heads = (
            "帮助", "注册", "余额", "兑换", "重画", "重绘", "图生图", "改图", "编辑",
            "生成", "生图",
        )
        return any(rest.startswith(head) for head in command_heads)

    def _parse_gpt_magic_command(self, raw: str) -> tuple:
        clean = str(raw or "").strip()
        if clean.startswith("/"):
            clean = clean[1:].strip()
        lower = clean.lower()
        if clean.startswith("酒狐魔法"):
            rest = clean[len("酒狐魔法"):].strip()
        elif lower.startswith("jh magic"):
            rest = clean[len("jh magic"):].strip()
        elif lower.startswith("jhmagic"):
            rest = clean[len("jhmagic"):].strip()
        elif lower.startswith("jhm"):
            rest = clean[len("jhm"):].strip()
        else:
            return "none", "", False

        if rest.startswith("+") or rest.startswith("＋"):
            return "draw", self._clean_prompt_after_trigger(rest[1:]), False

        compact_commands = [
            ("帮助", "help", False),
            ("注册", "register", False),
            ("余额", "balance", False),
            ("兑换", "redeem", False),
            ("重画", "draw", True),
            ("重绘", "draw", True),
            ("图生图", "draw", False),
            ("改图", "draw", False),
            ("编辑", "draw", False),
            ("生成", "draw", False),
            ("生图", "draw", False),
        ]
        for prefix, command, force_refresh in compact_commands:
            if rest.startswith(prefix):
                return command, self._clean_prompt_after_trigger(rest[len(prefix):]), force_refresh

        parts = rest.split(None, 1)
        head = parts[0].lower() if parts else ""
        tail = parts[1].strip() if len(parts) > 1 else ""
        if not head:
            return "help", "", False
        if head in ("help", "h", "?"):
            return "help", tail, False
        if head in ("register", "login", "reg"):
            return "register", tail, False
        if head in ("balance", "quota", "money"):
            return "balance", tail, False
        if head in ("redeem", "card", "key"):
            return "redeem", tail, False
        if head in ("redraw", "reroll", "refresh"):
            return "draw", tail, True
        if head in ("edit", "img2img", "image2image"):
            return "draw", tail, False
        return "draw", rest, False

    def _iter_event_components(self, event: AstrMessageEvent):
        try:
            comps = event.get_messages()
        except Exception:
            comps = None
        if comps is None:
            comps = getattr(getattr(event, "message_obj", None), "message", []) or []
        return list(comps or [])

    def _iter_image_components(self, components, include_reply_chain: bool = True):
        for comp in components or []:
            if isinstance(comp, Image):
                yield comp
            elif include_reply_chain and isinstance(comp, Reply):
                for item in self._iter_image_components(getattr(comp, "chain", None) or []):
                    yield item

    def _iter_reply_components(self, components):
        for comp in components or []:
            if isinstance(comp, Reply):
                yield comp

    async def _call_onebot_action(self, bot, action: str, **payload):
        api = getattr(bot, "api", None)
        if api and hasattr(api, "call_action"):
            return await api.call_action(action, **payload)
        if hasattr(bot, "call_action"):
            try:
                return await bot.call_action(action=action, **payload)
            except TypeError:
                return await bot.call_action(action, **payload)
        if api and hasattr(api, "post"):
            return await api.post(action, payload)
        raise RuntimeError("当前平台不支持 OneBot action 调用")

