    def _onebot_file_uri(self, path: Path) -> str:
        path = Path(path).resolve()
        try:
            return path.as_uri()
        except Exception:
            text = str(path).replace("\\", "/")
            if not text.startswith("/"):
                text = "/" + text
            return "file://" + text

    def _clip_favorite_text(self, text: str, limit: int = 3000) -> str:
        text = str(text or "").strip()
        limit = max(int(limit or 3000), 200)
        if len(text) <= limit:
            return text
        return text[: limit - 20].rstrip() + "\n...(已截断)"

    def _zayu_messages_path(self) -> Path:
        configured = str(getattr(self, "zayu_message_map_path", "") or "").strip()
        if configured:
            return Path(configured).expanduser()
        return Path(getattr(self, "zayu_message_store_path", self.data_dir / "zayu_messages.json"))

    def _zayu_replacement_values(self, value) -> list:
        if isinstance(value, list):
            return [str(item or "").strip() for item in value if str(item or "").strip()]
        text = str(value or "").strip()
        return [text] if text else []

    def _zayu_pick_replacement(self, value) -> str:
        values = self._zayu_replacement_values(value)
        return random.choice(values) if values else ""

    def _zayu_has_replacement_value(self, value) -> bool:
        return bool(self._zayu_replacement_values(value))

    def _zayu_message_data_has_active_replacements(self, data: dict) -> bool:
        if not isinstance(data, dict):
            return False
        messages = data.get("messages")
        if isinstance(messages, dict) and any(self._zayu_has_replacement_value(v) for v in messages.values()):
            return True
        entries = data.get("entries")
        if isinstance(entries, list):
            for entry in entries:
                if isinstance(entry, dict) and self._zayu_has_replacement_value(entry.get("replacement") or entry.get("zayu")):
                    return True
        for key in ("contains", "substring_replacements", "regex", "regex_replacements"):
            items = data.get(key)
            if isinstance(items, dict) and any(self._zayu_has_replacement_value(v) for v in items.values()):
                return True
            if isinstance(items, list):
                for item in items:
                    if isinstance(item, dict) and self._zayu_has_replacement_value(item.get("replacement") or item.get("zayu")):
                        return True
        return False

    def _merge_zayu_message_template(self, template_path: Path, dst_path: Path) -> bool:
        try:
            template = self._load_json_file_safe(template_path, default={})
            current = self._load_json_file_safe(dst_path, default={})
            if not isinstance(template, dict) or not isinstance(current, dict):
                return False
            template_entries = template.get("entries")
            if not isinstance(template_entries, list):
                return False
            current_entries = current.get("entries")
            if not isinstance(current_entries, list):
                current_entries = []
                current["entries"] = current_entries
            template_version = str(template.get("version") or "").strip()
            current_version = str(current.get("version") or "").strip()
            replace_existing = bool(template_version and current_version != template_version)
            index_by_id = {
                str(entry.get("id") or "").strip(): index
                for index, entry in enumerate(current_entries)
                if isinstance(entry, dict) and str(entry.get("id") or "").strip()
            }
            changed = False
            for entry in template_entries:
                if not isinstance(entry, dict):
                    continue
                entry_id = str(entry.get("id") or "").strip()
                if not entry_id:
                    continue
                if entry_id in index_by_id:
                    if replace_existing:
                        current_entries[index_by_id[entry_id]] = entry
                        changed = True
                    continue
                current_entries.append(entry)
                changed = True
            for key in ("version", "enabled_by", "usage"):
                if key in template and current.get(key) != template.get(key):
                    current[key] = template.get(key)
                    changed = True
            if changed:
                self._save_json_file_safe(dst_path, current)
            return changed
        except Exception as e:
            logger.warning(f"[ComfyUI] 合并杂鱼模式文案模板失败: {e}")
            return False

    def _load_zayu_messages_if_needed(self, force: bool = False) -> None:
        path = self._zayu_messages_path()
        try:
            mtime = path.stat().st_mtime if path.exists() else None
        except Exception:
            mtime = None
        if not force and mtime == getattr(self, "_zayu_message_cache_mtime", None):
            return

        exact = {}
        contains = []
        regex_items = []
        by_id = {}
        data = self._load_json_file_safe(path, default={}) if path.exists() else {}
        if isinstance(data, dict):
            messages = data.get("messages")
            if isinstance(messages, dict):
                for old, new in messages.items():
                    old = str(old or "")
                    new = self._zayu_replacement_values(new)
                    if old and new:
                        exact[old] = new

            entries = data.get("entries")
            if isinstance(entries, list):
                for entry in entries:
                    if not isinstance(entry, dict):
                        continue
                    old = str(entry.get("original") or entry.get("source") or "")
                    new = self._zayu_replacement_values(entry.get("replacement") or entry.get("zayu"))
                    mode = str(entry.get("mode") or "exact").strip().lower()
                    entry_id = str(entry.get("id") or "").strip()
                    if entry_id and new:
                        by_id[entry_id] = new
                    if not old or not new:
                        continue
                    if mode in {"contains", "substring"}:
                        contains.append((old, new))
                    elif mode in {"regex", "re"}:
                        regex_items.append((old, new))
                    else:
                        exact[old] = new

            for key in ("contains", "substring_replacements"):
                items = data.get(key)
                if isinstance(items, dict):
                    contains.extend((str(old), self._zayu_replacement_values(new)) for old, new in items.items() if str(old or "") and self._zayu_replacement_values(new))
                elif isinstance(items, list):
                    for item in items:
                        if isinstance(item, dict):
                            old = str(item.get("pattern") or item.get("original") or "")
                            new = self._zayu_replacement_values(item.get("replacement") or item.get("zayu"))
                            if old and new:
                                contains.append((old, new))

            items = data.get("regex") or data.get("regex_replacements")
            if isinstance(items, dict):
                regex_items.extend((str(old), self._zayu_replacement_values(new)) for old, new in items.items() if str(old or "") and self._zayu_replacement_values(new))
            elif isinstance(items, list):
                for item in items:
                    if isinstance(item, dict):
                        old = str(item.get("pattern") or item.get("original") or "")
                        new = self._zayu_replacement_values(item.get("replacement") or item.get("zayu"))
                        if old and new:
                            regex_items.append((old, new))

        self._zayu_exact_messages = exact
        self._zayu_contains_messages = contains
        self._zayu_regex_messages = regex_items
        self._zayu_entries_by_id = by_id
        self._zayu_message_cache_mtime = mtime

    def _zayu_format_replacement(self, text: str, values: dict = None) -> str:
        text = str(text or "")
        values = values or {}
        if not values:
            return text
        try:
            return text.format(**values)
        except Exception:
            return text

    def _zayu_message_by_id(self, message_id: str, default: str, **values) -> str:
        default_text = self._zayu_format_replacement(default, values)
        if not getattr(self, "zayu_mode_enabled", False):
            return default_text
        self._load_zayu_messages_if_needed()
        choices = (getattr(self, "_zayu_entries_by_id", {}) or {}).get(str(message_id or "").strip())
        if choices:
            picked = self._zayu_pick_replacement(choices)
            if picked:
                return self._zayu_format_replacement(picked, values)
        return self._zayu_translate_text(default_text)

    def _zayu_translate_text(self, text: str) -> str:
        if not getattr(self, "zayu_mode_enabled", False):
            return str(text or "")
        original = str(text or "")
        if not original:
            return original
        self._load_zayu_messages_if_needed()
        exact = getattr(self, "_zayu_exact_messages", {}) or {}
        if original in exact:
            return self._zayu_pick_replacement(exact[original])
        result = original
        for old, new in getattr(self, "_zayu_contains_messages", []) or []:
            if old in result:
                picked = self._zayu_pick_replacement(new)
                if picked:
                    result = result.replace(old, picked)
        for pattern, replacement in getattr(self, "_zayu_regex_messages", []) or []:
            try:
                picked = self._zayu_pick_replacement(replacement)
                if picked:
                    result = re.sub(pattern, picked, result)
            except Exception as e:
                logger.debug(f"[ComfyUI] 杂鱼模式正则替换失败: {pattern}: {e}")
        return result

    def _zayu_apply_to_component(self, component):
        if isinstance(component, Plain):
            component.text = self._zayu_translate_text(getattr(component, "text", ""))
            return
        if isinstance(component, Node):
            for item in list(getattr(component, "content", None) or []):
                self._zayu_apply_to_component(item)
            return
        if isinstance(component, Nodes):
            for node in list(getattr(component, "nodes", None) or getattr(component, "content", None) or []):
                self._zayu_apply_to_component(node)

    def _zayu_apply_to_result(self, result) -> bool:
        if not getattr(self, "zayu_mode_enabled", False) or not result:
            return False
        chain = getattr(result, "chain", None)
        if not chain:
            return False
        for component in list(chain):
            self._zayu_apply_to_component(component)
        return True

