    async def _image_component_to_path(self, image: Image):
        try:
            path = await image.convert_to_file_path()
            path = str(path or '').strip()
            if path and os.path.exists(path):
                return path
        except Exception as e:
            logger.warning(f"[ComfyUI] 图片转本地路径失败: {e}")
        return ""

    def _path_from_file_uri(self, value: str) -> str:
        text = str(value or "").strip()
        if not text.lower().startswith("file://"):
            return text
        try:
            parsed = urlparse(text)
            path = unquote(parsed.path or "")
            if parsed.netloc and not path.startswith("/"):
                path = f"//{parsed.netloc}/{path}"
            elif parsed.netloc:
                path = f"//{parsed.netloc}{path}"
            if re.match(r"^/[A-Za-z]:/", path):
                path = path[1:]
            return path.replace("/", os.sep)
        except Exception:
            return text

    def _onebot_image_data_field_values(self, data: dict) -> tuple:
        if not isinstance(data, dict):
            return "", "", []
        path = ""
        url = ""
        identifiers = []

        def add_identifier(value):
            text = str(value or "").strip()
            if text and text not in identifiers:
                identifiers.append(text)

        for key in ("path", "file_path", "filePath", "local_path", "localPath", "sourcePath"):
            text = self._path_from_file_uri(data.get(key))
            if text:
                path = text
                break
        for key in ("url", "originImageUrl", "origin_image_url", "download_url", "downloadUrl"):
            text = str(data.get(key) or "").strip()
            if text.startswith(("http://", "https://")):
                url = text
                break
        for key in ("file_id", "fileId", "fileUuid", "file_uuid", "file", "filename", "fileName", "uuid", "md5", "imageId"):
            add_identifier(data.get(key))
        return path, url, identifiers

    def _image_suffix_from_bytes(self, blob: bytes, fallback: str = ".png") -> str:
        if blob.startswith(b"\x89PNG\r\n\x1a\n"):
            return ".png"
        if blob.startswith(b"\xff\xd8\xff"):
            return ".jpg"
        if blob.startswith(b"RIFF") and blob[8:12] == b"WEBP":
            return ".webp"
        if blob.startswith(b"GIF87a") or blob.startswith(b"GIF89a"):
            return ".gif"
        return fallback if str(fallback or "").startswith(".") else ".png"

    def _onebot_image_cache_file(self, source: str, suffix: str = ".png") -> Path:
        cache_dir = Path(getattr(self, "data_dir", PLUGIN_DIR)) / "onebot_image_cache"
        cache_dir.mkdir(parents=True, exist_ok=True)
        digest = hashlib.sha256(str(source or uuid.uuid4().hex).encode("utf-8", errors="ignore")).hexdigest()[:24]
        suffix = suffix if str(suffix or "").startswith(".") else ".png"
        return cache_dir / f"{digest}_{uuid.uuid4().hex[:8]}{suffix}"

    def _onebot_image_base64_to_path(self, value: str, source: str = "") -> str:
        text = str(value or "").strip()
        if not text:
            return ""
        mime_suffix = ".png"
        if text.startswith("data:"):
            header, _, payload = text.partition(",")
            if "image/jpeg" in header or "image/jpg" in header:
                mime_suffix = ".jpg"
            elif "image/webp" in header:
                mime_suffix = ".webp"
            elif "image/gif" in header:
                mime_suffix = ".gif"
            text = payload
        if len(text) < 80:
            return ""
        try:
            blob = base64.b64decode(text, validate=False)
        except Exception:
            return ""
        if not blob:
            return ""
        suffix = self._image_suffix_from_bytes(blob, fallback=mime_suffix)
        target = self._onebot_image_cache_file(source or text[:64], suffix=suffix)
        try:
            target.write_bytes(blob)
            return str(target) if target.exists() else ""
        except Exception as e:
            logger.debug(f"[ComfyUI] OneBot 图片 base64 落盘失败: {e}")
            return ""

    async def _onebot_action_image_data_to_path(self, data, source: str = "") -> str:
        queue = [data]
        seen_ids = set()
        while queue:
            value = queue.pop(0)
            marker = id(value)
            if marker in seen_ids:
                continue
            seen_ids.add(marker)
            if isinstance(value, dict):
                path, url, identifiers = self._onebot_image_data_field_values(value)
                for candidate in [path] + identifiers:
                    candidate = self._path_from_file_uri(candidate)
                    if candidate and os.path.exists(candidate):
                        return candidate
                if url:
                    try:
                        image = Image(file=url, url=url)
                        path = await image.convert_to_file_path()
                        if path and os.path.exists(str(path)):
                            return str(path)
                    except Exception as e:
                        logger.debug(f"[ComfyUI] OneBot action 图片 URL 下载失败: {e}")
                for key in ("base64", "base64_data", "base64Data", "image_base64", "imageBase64", "data"):
                    raw = value.get(key)
                    if isinstance(raw, str):
                        path = self._onebot_image_base64_to_path(raw, source=source or str(value.get("file") or value.get("file_id") or ""))
                        if path:
                            return path
                for nested_key in ("data", "result", "file", "image"):
                    nested = value.get(nested_key)
                    if isinstance(nested, (dict, list)):
                        queue.append(nested)
            elif isinstance(value, list):
                queue.extend(item for item in value if isinstance(item, (dict, list)))
            elif isinstance(value, str):
                text = self._path_from_file_uri(value)
                if text and os.path.exists(text):
                    return text
                if text.startswith(("http://", "https://")):
                    try:
                        image = Image(file=text, url=text)
                        path = await image.convert_to_file_path()
                        if path and os.path.exists(str(path)):
                            return str(path)
                    except Exception as e:
                        logger.debug(f"[ComfyUI] OneBot action 字符串 URL 下载失败: {e}")
                path = self._onebot_image_base64_to_path(text, source=source)
                if path:
                    return path
        return ""

    async def _resolve_onebot_image_segment_path(self, event: AstrMessageEvent, seg: dict) -> str:
        seg_data = seg.get("data", {}) if isinstance(seg, dict) else {}
        if not isinstance(seg_data, dict):
            seg_data = {}
        local_path, url, identifiers = self._onebot_image_data_field_values(seg_data)
        for candidate in [local_path] + identifiers:
            candidate = self._path_from_file_uri(candidate)
            if candidate and os.path.exists(candidate):
                return candidate

        direct_candidates = []
        if url:
            direct_candidates.append((url, url))
        for identifier in identifiers[:4]:
            direct_candidates.append((identifier, url))
        for primary_file, primary_url in direct_candidates:
            if not primary_file and not primary_url:
                continue
            try:
                image = Image(file=primary_file or primary_url, url=primary_url)
                path = await image.convert_to_file_path()
                if path and os.path.exists(str(path)):
                    return str(path)
            except Exception as e:
                logger.debug(f"[ComfyUI] OneBot 图片段直接转本地路径失败: {e}")

        bot = getattr(event, "bot", None) if event else None
        if not bot or not identifiers:
            return ""
        action_payloads = []
        seen_payloads = set()

        def add_payload(action: str, payload: dict):
            key = (action, tuple(sorted((str(k), str(v)) for k, v in payload.items())))
            if key not in seen_payloads:
                seen_payloads.add(key)
                action_payloads.append((action, payload))

        for identifier in identifiers[:3]:
            add_payload("get_image", {"file": identifier})
            add_payload("get_file", {"file_id": identifier})
            add_payload("get_file", {"file": identifier})

        deadline = time.time() + 8.0
        for action, payload in action_payloads:
            remaining = deadline - time.time()
            if remaining <= 0:
                break
            try:
                data = await asyncio.wait_for(
                    self._call_onebot_action(bot, action, **payload),
                    timeout=max(0.8, min(3.0, remaining)),
                )
                path = await self._onebot_action_image_data_to_path(data, source=str(next(iter(payload.values()), "")))
                if path:
                    logger.info(f"[ComfyUI] OneBot/NapCat 通过 {action} 刷新图片成功")
                    return path
            except Exception as e:
                logger.debug(f"[ComfyUI] OneBot/NapCat 图片刷新失败: action={action} payload_keys={list(payload.keys())} err={e}")
        return ""

    async def _extract_reply_image_via_onebot(self, event: AstrMessageEvent, reply: Reply):
        paths = await self._extract_reply_images_via_onebot(event, reply, limit=1)
        return paths[0] if paths else ""

    async def _extract_reply_images_via_onebot(self, event: AstrMessageEvent, reply: Reply, limit: int = 8):
        paths = []
        if event.get_platform_name() != "aiocqhttp":
            return paths
        reply_id = str(getattr(reply, "id", "") or "").strip()
        if not reply_id:
            return paths
        try:
            msg_id = int(reply_id) if reply_id.isdigit() else reply_id
            data = await self._call_onebot_action(getattr(event, "bot", None), "get_msg", message_id=msg_id)
            segments = self._onebot_image_segments_from_message(data if isinstance(data, dict) else {})
            paths.extend(await self._image_paths_from_onebot_segments(segments, limit=limit, event=event))
        except Exception as e:
            logger.warning(f"[ComfyUI] 获取引用图片失败: {e}")
        return paths

    def _event_raw_dict(self, event: AstrMessageEvent) -> dict:
        for value in (
            getattr(event, "raw", None),
            getattr(getattr(event, "message_obj", None), "raw", None),
            getattr(getattr(event, "message_obj", None), "raw_message", None),
        ):
            if isinstance(value, dict):
                return value
        return {}

    def _normalize_qq_user_id(self, value) -> str:
        text = html_lib.unescape(str(value or "")).strip().strip("\"'")
        if not text or text.lower() in {"all", "everyone"}:
            return ""
        match = re.search(r"(?<!\d)(\d{5,12})(?!\d)", text)
        return match.group(1) if match else ""

    def _onebot_at_ids_from_text(self, text: str) -> list:
        ids = []

        def add(value):
            user_id = self._normalize_qq_user_id(value)
            if user_id and user_id not in ids:
                ids.append(user_id)

        text = str(text or "")
        for match in re.finditer(r"\[CQ:at,([^\]]+)\]", text, flags=re.I):
            attrs = {}
            for part in str(match.group(1) or "").split(","):
                if "=" not in part:
                    continue
                key, value = part.split("=", 1)
                attrs[key.strip().lower()] = value.strip()
            add(attrs.get("qq") or attrs.get("user_id") or attrs.get("uin"))
        for match in re.finditer(r"\[At:(\d{5,12})\]|```math\s*At:(\d{5,12})```", text, flags=re.I):
            add(match.group(1) or match.group(2))
        return ids

    def _extract_at_ids_from_dict(self, value) -> list:
        ids = []

        def add(raw):
            user_id = self._normalize_qq_user_id(raw)
            if user_id and user_id not in ids:
                ids.append(user_id)

        def visit(item, at_context: bool = False):
            if isinstance(item, str):
                for user_id in self._onebot_at_ids_from_text(item):
                    add(user_id)
                return
            if isinstance(item, list):
                for child in item:
                    visit(child, at_context=at_context)
                return
            if not isinstance(item, dict):
                return

            seg_type = str(item.get("type") or item.get("msgType") or item.get("elementType") or "").strip().lower()
            current_at_context = (
                at_context
                or seg_type in {"at", "mention"}
                or "atElement" in item
                or (
                    isinstance(item.get("data"), dict)
                    and str(item.get("data", {}).get("type") or "").strip().lower() in {"at", "mention"}
                )
            )

            if current_at_context:
                for key in ("qq", "user_id", "userId", "target", "uin", "atUin", "at_uin", "tinyId", "tiny_id"):
                    add(item.get(key))
                data = item.get("data")
                if isinstance(data, dict):
                    for key in ("qq", "user_id", "userId", "target", "uin", "atUin", "at_uin", "tinyId", "tiny_id"):
                        add(data.get(key))

            at_element = item.get("atElement")
            if isinstance(at_element, dict):
                for key in ("qq", "user_id", "userId", "target", "uin", "atUin", "at_uin", "tinyId", "tiny_id"):
                    add(at_element.get(key))
                visit(at_element, at_context=True)

            text_element = item.get("textElement")
            if isinstance(text_element, dict):
                text_has_at = any(
                    key in text_element
                    for key in ("atType", "atUid", "atNtUid", "atTinyId", "atUin", "at_uin", "uin")
                )
                if text_has_at:
                    for key in ("qq", "user_id", "userId", "target", "uin", "atUin", "at_uin", "atTinyId", "at_tiny_id"):
                        add(text_element.get(key))
                visit(text_element, at_context=text_has_at)

            for child in item.values():
                visit(child, at_context=current_at_context)

        visit(value)
        return ids

    def _extract_onebot_at_user_ids(self, event: AstrMessageEvent, text: str = "") -> list:
        ids = []

        def add_many(values):
            for value in values or []:
                user_id = self._normalize_qq_user_id(value)
                if user_id and user_id not in ids:
                    ids.append(user_id)

        text_candidates = [
            text,
            getattr(event, "message_str", ""),
            getattr(getattr(event, "message_obj", None), "raw_message", ""),
            getattr(getattr(event, "message_obj", None), "message_str", ""),
        ]
        raw = self._event_raw_dict(event)
        if isinstance(raw, dict):
            text_candidates.append(raw.get("raw_message", ""))
        for candidate in text_candidates:
            add_many(self._onebot_at_ids_from_text(candidate))

        for comp in self._iter_event_components(event):
            cls_name = comp.__class__.__name__.lower() if comp is not None else ""
            if cls_name == "at" or hasattr(comp, "qq"):
                add_many([getattr(comp, "qq", "")])
            if cls_name in {"at", "mention"}:
                for attr in ("target", "user_id", "userId", "uin"):
                    add_many([getattr(comp, attr, "")])
            data = getattr(comp, "data", None)
            if isinstance(data, dict):
                add_many(self._extract_at_ids_from_dict({"type": cls_name, "data": data}))
            if isinstance(comp, dict):
                add_many(self._extract_at_ids_from_dict(comp))
            else:
                add_many(self._onebot_at_ids_from_text(self._extract_plain_text_from_component(comp)))

        add_many(self._extract_at_ids_from_dict(raw))
        return ids

    def _strip_known_at_markers(self, text: str) -> str:
        text = str(text or "")
        text = re.sub(r"```math\s*At:\d{5,12}```", " ", text, flags=re.I)
        text = re.sub(r"\[At:\d{5,12}\]", " ", text, flags=re.I)
        text = re.sub(r"\[CQ:at,[^\]]+\]", " ", text, flags=re.I)
        return re.sub(r"\s+", " ", text).strip()

    def _is_avatar_redraw_prompt(self, event: AstrMessageEvent, prompt: str, target_ids: list = None) -> bool:
        target_ids = target_ids if target_ids is not None else self._extract_onebot_at_user_ids(event, prompt)
        if not target_ids:
            return False
        clean = self._strip_known_at_markers(prompt)
        if not clean:
            return True
        tokens = clean.split()
        if not tokens:
            return True
        return all(re.fullmatch(r"@[^@\s,，。;；:：/\\]+", token) for token in tokens)

    async def _onebot_avatar_url_candidates(self, event: AstrMessageEvent, user_id: str) -> list:
        urls = []

        def add_url(value):
            text = str(value or "").strip()
            if text.startswith(("http://", "https://")) and text not in urls:
                urls.append(text)

        def scan(value):
            if isinstance(value, dict):
                for key, child in value.items():
                    if str(key).lower() in {"avatar", "avatar_url", "avatarurl", "qlogo", "headimg", "headimgurl", "url"}:
                        add_url(child)
                    scan(child)
            elif isinstance(value, list):
                for child in value:
                    scan(child)

        bot = getattr(event, "bot", None)
        if not bot:
            return urls
        actions = []
        group_id = self._get_group_id(event)
        if group_id:
            actions.append(("get_group_member_info", {"group_id": int(group_id) if str(group_id).isdigit() else group_id, "user_id": int(user_id), "no_cache": True}))
        actions.append(("get_stranger_info", {"user_id": int(user_id), "no_cache": True}))
        for action, payload in actions:
            try:
                data = await asyncio.wait_for(self._call_onebot_action(bot, action, **payload), timeout=min(max(getattr(self, "avatar_redraw_timeout", 20), 3), 6))
                scan(data)
            except Exception:
                continue
        return urls

    def _avatar_url_from_template(self, template: str, user_id: str) -> str:
        template = str(template or "").strip()
        if not template:
            return ""
        try:
            return template.format(qq=user_id, user_id=user_id, uin=user_id)
        except Exception:
            return template.replace("{qq}", user_id).replace("{user_id}", user_id).replace("{uin}", user_id)

    def _avatar_image_suffix(self, content_type: str, data: bytes, url: str) -> str:
        content_type = str(content_type or "").split(";", 1)[0].strip().lower()
        if content_type == "image/png" or data.startswith(b"\x89PNG\r\n\x1a\n"):
            return ".png"
        if content_type in {"image/webp", "image/x-webp"} or data.startswith(b"RIFF") and b"WEBP" in data[:16]:
            return ".webp"
        if content_type in {"image/gif"} or data.startswith(b"GIF8"):
            return ".gif"
        suffix = Path(str(url or "").split("?", 1)[0]).suffix.lower()
        if suffix in {".png", ".jpg", ".jpeg", ".webp", ".gif", ".bmp"}:
            return suffix
        return ".jpg"

    def _looks_like_image_download(self, content_type: str, data: bytes) -> bool:
        if not data or len(data) < 32:
            return False
        if str(content_type or "").lower().startswith("image/"):
            return True
        return (
            data.startswith(b"\xff\xd8")
            or data.startswith(b"\x89PNG\r\n\x1a\n")
            or data.startswith(b"GIF8")
            or (data.startswith(b"RIFF") and b"WEBP" in data[:16])
        )

    async def _download_qq_avatar_image(self, event: AstrMessageEvent, user_id: str) -> tuple:
        user_id = self._normalize_qq_user_id(user_id)
        if not user_id:
            return "", "QQ 号无效"

        urls = await self._onebot_avatar_url_candidates(event, user_id)
        for url in (
            self._avatar_url_from_template(getattr(self, "avatar_redraw_url_template", ""), user_id),
            f"https://q1.qlogo.cn/g?b=qq&nk={user_id}&s=640",
            f"https://q.qlogo.cn/headimg_dl?dst_uin={user_id}&spec=640",
        ):
            if url and url not in urls:
                urls.append(url)
        if not urls:
            return "", "没有可用头像地址"

        target_dir = Path(getattr(self, "avatar_redraw_dir", self.data_dir / "avatar_redraw"))
        target_dir.mkdir(parents=True, exist_ok=True)
        timeout = aiohttp.ClientTimeout(total=max(int(getattr(self, "avatar_redraw_timeout", 20) or 20), 3), connect=6, sock_read=12)
        headers = {"User-Agent": "AstrBot-ComfyUI/6.0 avatar-redraw"}
        last_error = ""
        async with aiohttp.ClientSession(timeout=timeout, headers=headers) as session:
            for url in urls:
                try:
                    async with session.get(url) as resp:
                        if resp.status >= 400:
                            last_error = f"HTTP {resp.status}"
                            continue
                        data = await resp.read()
                        content_type = resp.headers.get("Content-Type", "")
                        if not self._looks_like_image_download(content_type, data):
                            last_error = "返回内容不是图片"
                            continue
                        suffix = self._avatar_image_suffix(content_type, data, url)
                        target = target_dir / f"avatar_{user_id}_{int(time.time())}_{uuid.uuid4().hex[:8]}{suffix}"
                        target.write_bytes(data)
                        logger.info(f"[ComfyUI] 已获取 @群友头像用于重绘: user={user_id} path={target}")
                        return str(target), ""
                except Exception as e:
                    last_error = self._short_user_error(e, 120) if hasattr(self, "_short_user_error") else str(e)
                    continue
        return "", last_error or "头像下载失败"

    def _generation_stats_avatar_cache_hit(self, *args, **kwargs):
        return self._generation_stats_feature._generation_stats_avatar_cache_hit(*args, **kwargs)

    async def _download_generation_stats_avatar_image(self, *args, **kwargs):
        return await self._generation_stats_feature._download_generation_stats_avatar_image(*args, **kwargs)

    async def _enrich_generation_stats_rank_view(self, *args, **kwargs):
        return await self._generation_stats_feature._enrich_generation_stats_rank_view(*args, **kwargs)

    def _walk_nested_reply_elements(self, value):
        if isinstance(value, dict):
            reply = value.get("replyElement")
            if isinstance(reply, dict):
                yield reply
            if value.get("type") == "reply" and isinstance(value.get("data"), dict):
                yield value.get("data")
            if any(key in value for key in ("replyMsgId", "replyMsgSeq", "sourceMsgIdInRecords", "sourceMsgText", "sourceMsg")):
                yield value
            for item in value.values():
                yield from self._walk_nested_reply_elements(item)
        elif isinstance(value, list):
            for item in value:
                yield from self._walk_nested_reply_elements(item)

    def _reply_message_ids_from_raw_reply(self, reply: dict) -> list:
        values = []

        def add(value):
            text = str(value or "").strip()
            if not text:
                return
            if text not in values:
                values.append(text)

        for key in (
            "id", "replyMsgId", "sourceMsgIdInRecords", "sourceMsgId", "message_id", "messageId",
            "msgId", "msgSeq", "replyMsgSeq", "sourceMsgSeq", "real_id", "realId",
        ):
            add((reply or {}).get(key))
        source = (reply or {}).get("sourceMsg")
        if isinstance(source, dict):
            for key in ("message_id", "messageId", "msgId", "msgSeq", "real_id", "realId"):
                add(source.get(key))
        return values

    def _raw_reply_image_segments(self, reply: dict) -> list:
        segments = []
        segments.extend(self._onebot_image_segments_from_message(reply or {}))
        for key in ("sourceMsg", "sourceMsgText", "sourceMsgElements", "elements", "message"):
            value = (reply or {}).get(key)
            if isinstance(value, dict):
                segments.extend(self._onebot_image_segments_from_message(value))
            elif isinstance(value, list):
                segments.extend(self._onebot_image_segments_from_message({"message": value}))
            elif isinstance(value, str):
                segments.extend(self._onebot_image_segments_from_raw(value))
        deduped = []
        seen = set()
        for seg in segments:
            data = seg.get("data", {}) if isinstance(seg, dict) else {}
            key = (
                str(data.get("file") or ""),
                str(data.get("file_id") or data.get("fileId") or ""),
                str(data.get("path") or ""),
                str(data.get("url") or ""),
                str(data.get("md5") or ""),
            )
            if key in seen:
                continue
            seen.add(key)
            deduped.append(seg)
        return deduped

    async def _extract_raw_reply_images_via_onebot(self, event: AstrMessageEvent, limit: int = 8) -> list:
        paths = []
        if event.get_platform_name() != "aiocqhttp":
            return paths
        max_paths = max(int(limit or 1), 1)
        seen = set()

        async def add_paths(new_paths):
            for path in new_paths or []:
                key = os.path.abspath(path) if os.path.exists(path) else str(path)
                if not key or key in seen:
                    continue
                seen.add(key)
                paths.append(path)
                if len(paths) >= max_paths:
                    return True
            return False

        raw = self._event_raw_dict(event)
        replies = []
        reply_seen = set()
        for reply in self._walk_nested_reply_elements(raw):
            if not isinstance(reply, dict):
                continue
            key = json.dumps(reply, ensure_ascii=False, sort_keys=True, default=str)[:1000]
            if key in reply_seen:
                continue
            reply_seen.add(key)
            replies.append(reply)

        for reply in replies:
            direct_segments = self._raw_reply_image_segments(reply)
            if direct_segments:
                logger.info(f"[ComfyUI] 酒狐看看从原始引用卡片解析到图片段: segments={len(direct_segments)}")
                if await add_paths(await self._image_paths_from_onebot_segments(direct_segments, limit=max_paths - len(paths), event=event)):
                    return paths
            for reply_id in self._reply_message_ids_from_raw_reply(reply):
                try:
                    payload_id = int(reply_id) if str(reply_id).isdigit() else reply_id
                    data = await self._call_onebot_action(getattr(event, "bot", None), "get_msg", message_id=payload_id)
                    segments = self._onebot_image_segments_from_message(data if isinstance(data, dict) else {})
                    if segments:
                        logger.info(f"[ComfyUI] 酒狐看看通过原始引用 ID 获取图片: message_id={reply_id} segments={len(segments)}")
                    if await add_paths(await self._image_paths_from_onebot_segments(segments, limit=max_paths - len(paths), event=event)):
                        return paths
                except Exception:
                    continue
        return paths

    async def _extract_source_image_paths(self, event: AstrMessageEvent, limit: int = 8, reply_first: bool = False):
        components = self._iter_event_components(event)
        paths = []
        seen = set()
        max_paths = max(int(limit or 1), 1)

        async def add_path(path: str):
            path = str(path or "").strip()
            if not path:
                return
            key = os.path.abspath(path) if os.path.exists(path) else path
            if key in seen:
                return
            seen.add(key)
            paths.append(path)

        async def collect_attached_images():
            for image in self._iter_image_components(components, include_reply_chain=not reply_first):
                path = await self._image_component_to_path(image)
                await add_path(path)
                if len(paths) >= max_paths:
                    return paths
            for path in await self._extract_direct_image_paths_from_event(event, limit=max_paths - len(paths)):
                await add_path(path)
                if len(paths) >= max_paths:
                    return paths

        async def collect_reply_images():
            for reply in self._iter_reply_components(components):
                for image in self._iter_image_components(getattr(reply, "chain", None) or []):
                    path = await self._image_component_to_path(image)
                    await add_path(path)
                    if len(paths) >= max_paths:
                        return paths
                for path in await self._extract_reply_images_via_onebot(event, reply, limit=max_paths):
                    await add_path(path)
                    if len(paths) >= max_paths:
                        return paths
            for path in await self._extract_raw_reply_images_via_onebot(event, limit=max_paths):
                await add_path(path)
                if len(paths) >= max_paths:
                    return paths
            return paths

        if reply_first:
            await collect_reply_images()
            if len(paths) < max_paths:
                await collect_attached_images()
        else:
            await collect_attached_images()
            if len(paths) < max_paths:
                await collect_reply_images()
        return paths

    async def _extract_source_image_path(self, event: AstrMessageEvent):
        paths = await self._extract_source_image_paths(event, limit=1)
        return paths[0] if paths else ""

    def _look_recent_session_key(self, event: AstrMessageEvent) -> str:
        platform = str(event.get_platform_name() if event else "" or "unknown").strip() or "unknown"
        group_id = self._get_group_id(event) if event and self._is_group_message(event) else ""
        if group_id:
            return f"{platform}:group:{group_id}"
        user_id = str(event.get_sender_id() if event else "" or "").strip()
        return f"{platform}:private:{user_id}" if user_id else ""

    async def _remember_look_recent_images_from_event(self, event: AstrMessageEvent, raw_candidates: list = None) -> None:
        if event is None:
            return
        session_key = self._look_recent_session_key(event)
        if not session_key:
            return
        self_id = str(self._get_self_id(event) or "").strip()
        sender_id = str(event.get_sender_id() or "").strip()
        if self_id and sender_id and sender_id == self_id:
            return
        raw_candidates = raw_candidates or self._event_plain_text_candidates(event)
        if any(self._is_look_trigger(text, event=event) for text in raw_candidates or []):
            return
        try:
            limit = max(1, min(int(getattr(self, "look_vision_max_images", 6) or 6), 8))
            paths = await self._extract_direct_image_paths_from_event(event, limit=limit)
        except Exception as e:
            logger.warning(f"[ComfyUI] 酒狐看看最近图缓存失败: {e}")
            return
        paths = [str(path or "").strip() for path in paths or [] if str(path or "").strip() and os.path.exists(str(path or "").strip())]
        if not paths:
            return
        now = time.time()
        async with self._look_recent_session_image_lock:
            cache = self._look_recent_session_image_cache
            stale = [
                key for key, entry in (cache or {}).items()
                if now - float((entry or {}).get("time") or 0) > 300
            ]
            for key in stale:
                cache.pop(key, None)
            cache[session_key] = {
                "paths": paths,
                "time": now,
                "sender_id": sender_id,
            }
            if len(cache) > 300:
                for key, _entry in sorted(cache.items(), key=lambda kv: float((kv[1] or {}).get("time") or 0))[: len(cache) - 240]:
                    cache.pop(key, None)
        logger.info(f"[ComfyUI] 酒狐看看已缓存会话最近图: session={session_key} images={len(paths)}")

    async def _get_look_recent_session_images(self, event: AstrMessageEvent, limit: int = 8, max_age_seconds: int = 180) -> list:
        session_key = self._look_recent_session_key(event)
        if not session_key:
            return []
        now = time.time()
        async with self._look_recent_session_image_lock:
            entry = (self._look_recent_session_image_cache or {}).get(session_key)
            if not entry:
                return []
            age = now - float((entry or {}).get("time") or 0)
            if age > max(float(max_age_seconds or 180), 1.0):
                self._look_recent_session_image_cache.pop(session_key, None)
                return []
            paths = [
                str(path or "").strip()
                for path in (entry.get("paths") or [])
                if str(path or "").strip() and os.path.exists(str(path or "").strip())
            ]
            if paths:
                entry["paths"] = paths
            else:
                self._look_recent_session_image_cache.pop(session_key, None)
        return paths[:max(int(limit or 1), 1)]

    def _look_private_image_user_key(self, event: AstrMessageEvent) -> str:
        return str(event.get_sender_id() or "").strip()

    async def _remember_look_private_images_from_event(self, event: AstrMessageEvent, raw_candidates: list = None) -> None:
        if event is None or self._is_group_message(event):
            return
        user_key = self._look_private_image_user_key(event)
        if not user_key:
            return
        self_id = str(self._get_self_id(event) or "").strip()
        if self_id and user_key == self_id:
            return
        raw_candidates = raw_candidates or self._event_plain_text_candidates(event)
        if any(self._is_look_trigger(text, event=event) for text in raw_candidates or []):
            return
        try:
            limit = max(1, min(int(getattr(self, "look_vision_max_images", 6) or 6), 8))
            paths = await self._extract_source_image_paths(event, limit=limit, reply_first=False)
        except Exception as e:
            logger.warning(f"[ComfyUI] 酒狐看看私聊图片缓存失败: {e}")
            return
        paths = [str(path or "").strip() for path in paths or [] if str(path or "").strip()]
        if not paths:
            return
        async with self._look_private_image_lock:
            waiters = list(self._look_private_image_waiters.pop(user_key, []) or [])
            if not waiters:
                self._look_private_image_cache[user_key] = {"paths": paths, "time": time.time()}
        for fut in waiters:
            if fut and not fut.done():
                fut.set_result(list(paths))
        logger.info(f"[ComfyUI] 酒狐看看已接收私聊图片: user={user_key} images={len(paths)} waiters={len(waiters)}")

    def _onebot_history_messages(self, payload) -> list:
        if payload is None:
            return []
        if isinstance(payload, list):
            return [item for item in payload if isinstance(item, dict)]
        if not isinstance(payload, dict):
            return []
        if isinstance(payload.get("message"), list) and (
            payload.get("message_id") is not None
            or payload.get("user_id") is not None
            or payload.get("raw_message") is not None
        ):
            return [payload]
        for key in ("messages", "msgs", "message_list", "data"):
            value = payload.get(key)
            if isinstance(value, list):
                return [item for item in value if isinstance(item, dict)]
            if isinstance(value, dict):
                nested = self._onebot_history_messages(value)
                if nested:
                    return nested
        return []

    def _onebot_message_time(self, msg: dict) -> float:
        for value in (
            (msg or {}).get("time"),
            (msg or {}).get("msg_time"),
            (msg or {}).get("message_time"),
            ((msg or {}).get("raw") or {}).get("msgTime") if isinstance((msg or {}).get("raw"), dict) else None,
        ):
            try:
                if value is not None and str(value).strip():
                    return float(value)
            except Exception:
                continue
        return 0.0

    def _event_message_time(self, event: AstrMessageEvent) -> float:
        for value in (
            getattr(event, "time", None),
            getattr(getattr(event, "message_obj", None), "time", None),
            ((getattr(event, "raw", None) or {}).get("time") if isinstance(getattr(event, "raw", None), dict) else None),
        ):
            try:
                if value is not None and str(value).strip():
                    return float(value)
            except Exception:
                continue
        return time.time()

    def _onebot_message_sequence(self, msg: dict):
        raw = (msg or {}).get("raw")
        if not isinstance(raw, dict):
            raw = {}
        for value in (
            (msg or {}).get("message_seq"),
            (msg or {}).get("real_seq"),
            raw.get("msgSeq"),
            raw.get("cntSeq"),
        ):
            try:
                text = str(value or "").strip()
                if text and re.fullmatch(r"\d+", text):
                    return int(text)
            except Exception:
                continue
        return None

    def _onebot_image_segments_from_raw(self, raw_message: str) -> list:
        segments = []
        for match in re.finditer(r"\[CQ:image,([^\]]+)\]", str(raw_message or ""), re.I):
            data = {}
            for part in str(match.group(1) or "").split(","):
                if "=" not in part:
                    continue
                key, value = part.split("=", 1)
                data[key.strip()] = html_lib.unescape(value.strip())
            if data:
                segments.append({"type": "image", "data": data})
        return segments

    def _onebot_image_segments_from_pic_element(self, pic: dict) -> list:
        if not isinstance(pic, dict):
            return []
        data = {}
        source_path = str(pic.get("sourcePath") or "").strip()
        file_name = str(pic.get("fileName") or "").strip()
        origin_url = str(pic.get("originImageUrl") or "").strip()
        file_uuid = str(pic.get("fileUuid") or "").strip()
        md5 = str(pic.get("md5") or "").strip()
        if source_path:
            data["path"] = source_path
        if source_path and os.path.exists(source_path):
            data["file"] = source_path
        elif file_name:
            data["file"] = file_name
        elif file_uuid:
            data["file"] = file_uuid
        if file_uuid:
            data["file_id"] = file_uuid
        if md5:
            data["md5"] = md5
        if origin_url.startswith("http://") or origin_url.startswith("https://"):
            data["url"] = origin_url
        if data:
            return [{"type": "image", "data": data}]
        return []

    def _onebot_image_segments_from_message(self, msg: dict) -> list:
        segments = []

        def add_segment(seg):
            if seg is None:
                return
            if isinstance(seg, str):
                segments.extend(self._onebot_image_segments_from_raw(seg))
                return
            if not isinstance(seg, dict):
                return
            if seg.get("type") == "image":
                data = seg.get("data") if isinstance(seg.get("data"), dict) else {}
                if not data:
                    data = {
                        key: seg.get(key)
                        for key in ("file", "url", "file_id", "fileId", "path", "fileUuid", "sourcePath", "originImageUrl")
                        if seg.get(key)
                    }
                if data:
                    segments.append({"type": "image", "data": dict(data)})
                return
            if isinstance(seg.get("picElement"), dict):
                segments.extend(self._onebot_image_segments_from_pic_element(seg.get("picElement")))
                return
            if isinstance(seg.get("data"), dict) and seg.get("data", {}).get("picElement"):
                segments.extend(self._onebot_image_segments_from_pic_element(seg.get("data", {}).get("picElement")))

        message = (msg or {}).get("message")
        if isinstance(message, list):
            for seg in message:
                add_segment(seg)
        elif isinstance(message, str):
            add_segment(message)
        segments.extend(self._onebot_image_segments_from_raw(str((msg or {}).get("raw_message") or "")))

        raw = (msg or {}).get("raw")
        if isinstance(raw, dict):
            for seg in raw.get("elements") or []:
                add_segment(seg)
        for seg in (msg or {}).get("elements") or []:
            add_segment(seg)

        deduped = []
        seen = set()
        for seg in segments:
            data = seg.get("data", {}) if isinstance(seg, dict) else {}
            key = (
                str(data.get("file") or ""),
                str(data.get("file_id") or data.get("fileId") or ""),
                str(data.get("path") or ""),
                str(data.get("url") or ""),
                str(data.get("md5") or ""),
            )
            if key in seen:
                continue
            seen.add(key)
            deduped.append(seg)
        return deduped

    def _onebot_image_segments_from_event(self, event: AstrMessageEvent) -> list:
        candidates = []

        def add_candidate(value):
            if isinstance(value, dict):
                candidates.append(value)
            elif isinstance(value, list):
                candidates.append({"message": value})
            elif isinstance(value, str) and value.strip():
                candidates.append({"raw_message": value})

        add_candidate(self._event_raw_dict(event))
        message_obj = getattr(event, "message_obj", None)
        for value in (
            getattr(event, "raw_message", None),
            getattr(message_obj, "raw_message", None),
            getattr(event, "message", None),
            getattr(message_obj, "message", None),
        ):
            add_candidate(value)
        try:
            add_candidate(self._iter_event_components(event))
        except Exception:
            pass

        segments = []
        seen = set()
        for candidate in candidates:
            for seg in self._onebot_image_segments_from_message(candidate):
                data = seg.get("data", {}) if isinstance(seg, dict) else {}
                key = (
                    str(data.get("file") or ""),
                    str(data.get("file_id") or data.get("fileId") or ""),
                    str(data.get("path") or ""),
                    str(data.get("url") or ""),
                    str(data.get("md5") or ""),
                )
                if key in seen:
                    continue
                seen.add(key)
                segments.append(seg)
        return segments

    async def _extract_direct_image_paths_from_event(self, event: AstrMessageEvent, limit: int = 8) -> list:
        paths = []
        seen = set()
        max_paths = max(int(limit or 1), 1)

        async def add_path(path: str):
            path = str(path or "").strip()
            if not path:
                return False
            key = os.path.abspath(path) if os.path.exists(path) else path
            if key in seen:
                return False
            seen.add(key)
            paths.append(path)
            return len(paths) >= max_paths

        for image in self._iter_image_components(self._iter_event_components(event), include_reply_chain=False):
            if await add_path(await self._image_component_to_path(image)):
                return paths
        for path in await self._image_paths_from_onebot_segments(
            self._onebot_image_segments_from_event(event),
            limit=max_paths - len(paths),
            event=event,
        ):
            if await add_path(path):
                return paths
        return paths

    async def _image_paths_from_onebot_segments(self, segments, limit: int = 8, event: AstrMessageEvent = None) -> list:
        paths = []
        seen = set()
        max_paths = max(int(limit or 1), 1)
        for seg in segments or []:
            if not isinstance(seg, dict) or seg.get("type") != "image":
                continue
            path = await self._resolve_onebot_image_segment_path(event, seg)
            if not path:
                continue
            key = os.path.abspath(path) if os.path.exists(path) else path
            if key in seen:
                continue
            seen.add(key)
            paths.append(path)
            if len(paths) >= max_paths:
                break
        return paths

    async def _fetch_onebot_private_history_messages(self, event: AstrMessageEvent, user_key: str, count: int = 20) -> list:
        bot = getattr(event, "bot", None)
        if not bot or not user_key:
            return []
        uid = int(user_key) if str(user_key).isdigit() else user_key
        safe_count = max(1, min(int(count or 20), 50))
        action_payloads = [
            ("get_friend_msg_history", {"user_id": uid, "count": safe_count, "reverseOrder": False}),
            ("get_friend_msg_history", {"user_id": uid, "count": safe_count, "reverse_order": False}),
            ("get_friend_msg_history", {"user_id": uid, "message_seq": "0", "count": safe_count, "reverseOrder": False}),
            ("get_private_msg_history", {"user_id": uid, "count": safe_count}),
            ("get_msg_history", {"message_type": "private", "user_id": uid, "count": safe_count}),
        ]
        for action, payload in action_payloads:
            try:
                data = await asyncio.wait_for(self._call_onebot_action(bot, action, **payload), timeout=3)
                messages = self._onebot_history_messages(data)
                if messages:
                    log_cache = getattr(self, "_look_private_history_log_cache", None)
                    if not isinstance(log_cache, dict):
                        log_cache = {}
                        self._look_private_history_log_cache = log_cache
                    log_key = f"{user_key}:{action}:{safe_count}"
                    signature = (
                        len(messages),
                        self._onebot_message_sequence(messages[-1]),
                        self._onebot_message_time(messages[-1]),
                    )
                    if log_cache.get(log_key) != signature:
                        log_cache[log_key] = signature
                        logger.debug(f"[ComfyUI] 酒狐看看已通过 {action} 查询私聊历史: user={user_key} messages={len(messages)}")
                    return messages
            except Exception:
                continue
        return []

    async def _look_private_history_marker(self, event: AstrMessageEvent, user_key: str) -> dict:
        marker = {"time": self._event_message_time(event), "seq": None}
        messages = await self._fetch_onebot_private_history_messages(event, user_key, count=5)
        if not messages:
            return marker
        best_seq = None
        for msg in messages:
            sender = str(msg.get("user_id") or msg.get("sender_id") or ((msg.get("sender") or {}).get("user_id") if isinstance(msg.get("sender"), dict) else "") or "").strip()
            if sender and sender != user_key:
                continue
            msg_seq = self._onebot_message_sequence(msg)
            if msg_seq is not None and (best_seq is None or msg_seq > best_seq):
                best_seq = msg_seq
        marker["seq"] = best_seq
        return marker

    async def _fetch_look_private_images_from_history(
        self,
        event: AstrMessageEvent,
        user_key: str,
        limit: int = 8,
        since_time: float = 0.0,
        after_seq=None,
    ) -> list:
        messages = await self._fetch_onebot_private_history_messages(event, user_key, count=20)
        if not messages:
            return []
        image_paths = []
        seen = set()
        max_paths = max(int(limit or 1), 1)
        for msg in messages:
            sender = str(msg.get("user_id") or msg.get("sender_id") or ((msg.get("sender") or {}).get("user_id") if isinstance(msg.get("sender"), dict) else "") or "").strip()
            if sender and sender != user_key:
                continue
            msg_time = self._onebot_message_time(msg)
            msg_seq = self._onebot_message_sequence(msg)
            if after_seq is not None and msg_seq is not None and msg_seq <= after_seq:
                continue
            if msg_time:
                if since_time and msg_time < float(since_time):
                    continue
            elif after_seq is None or msg_seq is None or msg_seq <= after_seq:
                continue
            segments = self._onebot_image_segments_from_message(msg)
            if not segments:
                logger.info(
                    f"[ComfyUI] 酒狐看看私聊历史新消息无可解析图片段: "
                    f"user={user_key} time={msg_time or '-'} seq={msg_seq if msg_seq is not None else '-'} "
                    f"keys={','.join(list(msg.keys())[:12])}"
                )
                continue
            for path in await self._image_paths_from_onebot_segments(segments, limit=max_paths - len(image_paths), event=event):
                key = os.path.abspath(path) if os.path.exists(path) else path
                if key in seen:
                    continue
                seen.add(key)
                image_paths.append(path)
                if len(image_paths) >= max_paths:
                    return image_paths
        return image_paths

    async def _wait_for_look_private_images(self, event: AstrMessageEvent, limit: int = 8, wait_seconds: int = 10) -> list:
        user_key = self._look_private_image_user_key(event)
        if not user_key:
            return []
        wait_seconds = max(float(wait_seconds or 10), 0.1)
        started = time.time()
        deadline = started + wait_seconds
        marker = await self._look_private_history_marker(event, user_key)
        since_time = max(float(marker.get("time") or 0), self._event_message_time(event), started - 1.0)
        after_seq = marker.get("seq")
        ttl = max(wait_seconds, 10.0)
        while True:
            now = time.time()
            async with self._look_private_image_lock:
                stale_users = [
                    key for key, entry in (self._look_private_image_cache or {}).items()
                    if now - float((entry or {}).get("time") or 0) > ttl
                ]
                for key in stale_users:
                    self._look_private_image_cache.pop(key, None)
                cached = self._look_private_image_cache.pop(user_key, None)
                if cached:
                    paths = [str(path or "").strip() for path in (cached.get("paths") or []) if str(path or "").strip()]
                    if paths:
                        return paths[:max(int(limit or 1), 1)]

            history_paths = await self._fetch_look_private_images_from_history(
                event,
                user_key,
                limit=limit,
                since_time=since_time,
                after_seq=after_seq,
            )
            if history_paths:
                return history_paths

            remaining = deadline - time.time()
            if remaining <= 0:
                return []
            async with self._look_private_image_lock:
                fut = asyncio.get_running_loop().create_future()
                self._look_private_image_waiters.setdefault(user_key, []).append(fut)
            try:
                paths = await asyncio.wait_for(fut, timeout=min(remaining, 1.0))
                paths = [str(path or "").strip() for path in (paths or []) if str(path or "").strip()]
                if paths:
                    return paths[:max(int(limit or 1), 1)]
            except asyncio.TimeoutError:
                pass
            finally:
                async with self._look_private_image_lock:
                    waiters = self._look_private_image_waiters.get(user_key) or []
                    waiters = [item for item in waiters if item is not fut and not item.done()]
                    if waiters:
                        self._look_private_image_waiters[user_key] = waiters
                    else:
                        self._look_private_image_waiters.pop(user_key, None)

    def _is_look_trigger(self, text: str, event: AstrMessageEvent = None) -> bool:
        raw = self._plain_trigger_text(text)
        raw = re.sub(r"^[!！/]+", "", raw).strip()
        return bool(re.match(r"^(?:酒狐看看|jh看看|jh\s+看看|酒狐识图|酒狐識圖|jh识图|jh\s+识图)(?:\s|$)", raw, re.I))

    def _look_command_body(self, text: str) -> str:
        raw = self._plain_trigger_text(text)
        raw = re.sub(r"^[!！/]+", "", raw).strip()
        return re.sub(r"^(?:酒狐看看|jh看看|jh\s+看看|酒狐识图|酒狐識圖|jh识图|jh\s+识图)\s*", "", raw, flags=re.I).strip()

