    async def initialize(self):
        try:
            self._ensure_llm_draw_tool_registered()
            old_disabled = self.context.deactivate_llm_tool("comfyui_txt2img")
            activated = self.context.activate_llm_tool("jiuhu_draw_image")
            if activated:
                suffix = "，旧 comfyui_txt2img 已停用" if old_disabled else ""
                logger.info(f"[ComfyUI] LLM 绘图函数已激活: jiuhu_draw_image{suffix}")
            else:
                logger.warning("[ComfyUI] 未找到 LLM 绘图函数 jiuhu_draw_image，模型可能无法调用画图工具")
        except Exception as e:
            logger.warning(f"[ComfyUI] LLM 绘图函数激活失败: {e}")
        if self._maybe_start_image_audit_auto_deploy():
            logger.info("[ComfyUI] 酒狐审核模型未检测到，已启动自动部署下载任务")
        if self.gpt_magic:
            try:
                await self.gpt_magic.start_webui(
                    self._build_gpt_magic_comfy_status,
                    self._handle_gpt_magic_model_action,
                )
            except Exception as e:
                logger.error(f"[GPT Magic] WebUI 启动异常: {e}")
                logger.error(traceback.format_exc())
            try:
                await self.gpt_magic.start_gallery_webui()
            except Exception as e:
                logger.error(f"[GPT Magic] WineFox 收藏展示页启动异常: {e}")
                logger.error(traceback.format_exc())
        if self.api and getattr(self.api, "auto_refresh_lora_list", True):
            try:
                loras, warn = await self.api.fetch_lora_list(force=True, allow_cache_fallback=False)
                if not self._is_no_cache_lora_fetch_failure(warn):
                    self._cleanup_stale_lora_mappings(loras)
                self._auto_update_schema()
                if warn:
                    logger.warning(f"[ComfyUI] LoRA 列表初始化提示: {warn}")
                else:
                    logger.info(f"[ComfyUI] 🧩 LoRA 列表已初始化: {len(loras)} 个")
            except Exception as e:
                logger.warning(f"[ComfyUI] 初始化 LoRA 列表失败: {e}")
        if self.api:
            try:
                checkpoint_names, checkpoint_warn = await self._fetch_comfyui_checkpoint_names()
                self._auto_update_schema()
                if checkpoint_warn:
                    logger.warning(f"[ComfyUI] Checkpoint 列表初始化提示: {checkpoint_warn}")
                elif checkpoint_names:
                    logger.info(f"[ComfyUI] 🧬 Checkpoint 列表已初始化: {len(checkpoint_names)} 个")
            except Exception as e:
                logger.warning(f"[ComfyUI] 初始化 Checkpoint 列表失败: {e}")
        logger.info("[ComfyUI] 🎨 插件初始化完成，绘图入口限定为 酒狐来点 / LLM 函数 jiuhu_draw_image")

    async def terminate(self):
        self._uninstall_test_mode_log_handler()
        _cached_normalize_profile_match_key.cache_clear()
        _cached_normalize_lora_match_key.cache_clear()
        for task in list(getattr(self, "_test_mode_log_tasks", set()) or []):
            try:
                task.cancel()
            except Exception:
                pass
        getattr(self, "_test_mode_log_tasks", set()).clear()
        for attr in ("_lora_background_tasks", "_paint_background_tasks", "_video_background_tasks"):
            tasks = getattr(self, attr, set()) or set()
            for task in list(tasks):
                try:
                    task.cancel()
                except Exception:
                    pass
            try:
                tasks.clear()
            except Exception:
                pass
        if self.gpt_magic:
            try:
                await self.gpt_magic.stop_gallery_webui()
            except Exception as e:
                logger.warning(f"[GPT Magic] WineFox 收藏展示页停止异常: {e}")
            try:
                await self.gpt_magic.stop_webui()
            except Exception as e:
                logger.warning(f"[GPT Magic] WebUI 停止异常: {e}")

    # ====== 核心绘图逻辑 ======
    async def _handle_paint_logic(self, event: AstrMessageEvent, direct_send: bool):
        """处理画图的核心逻辑"""
        try:
            full_message = event.message_str.strip()
            parts = full_message.split(' ', 1)
            prompt = parts[1].strip() if len(parts) > 1 else ""
            async for result in self._handle_paint_prompt(event, prompt, direct_send=direct_send):
                yield result
        except Exception as e:
            logger.error(f"[ComfyUI] 绘图异常: {e}")
            logger.error(traceback.format_exc())
            yield event.plain_result(f"❌ 执行出错：{str(e)[:50]}")
    # ===== 探针：测试 event.send() 是否触发 on_decorating_result =====
    @filter.command("comfy_probe_send")
    async def cmd_probe_send(self, event: AstrMessageEvent):
        """探测 event.send() 是否会触发 on_decorating_result"""
        user_id = str(event.get_sender_id())
        if user_id not in self.admin_user_ids:
            yield event.plain_result("🚫 仅管理员可用")
            return

        # 设置一个标记
        event.set_extra("_probe_send_test", True)
        logger.info("[探针] 已设置 _probe_send_test 标记")

        # 通过 event.send 发送一条消息
        try:
            await event.send(event.plain_result("探针消息：这是通过 event.send() 发出的"))
            logger.info("[探针] event.send() 调用完成")
        except Exception as e:
            logger.error(f"[探针] event.send() 失败: {e}")

        yield event.plain_result("探针完成，请检查日志中是否出现 '[探针] on_decorating_result 被 event.send 触发'")
    # ===== 探针结束 =====

    def _match_compact_head(self, body: str, aliases: list):
        text = str(body or "").lstrip()
        lower = text.lower()
        for alias in sorted([str(x) for x in aliases if str(x)], key=len, reverse=True):
            if lower.startswith(alias.lower()):
                return alias, text[len(alias):].strip()
        return "", text

    def _normalize_compact_subcommand_rest(self, rest: str, aliases: list, nested: dict = None) -> str:
        rest = str(rest or "").strip()
        if not rest:
            return ""
        head, tail = self._match_compact_head(rest, aliases)
        if not head:
            return rest
        nested = nested or {}
        nested_aliases = nested.get(head.lower()) or nested.get(head) or []
        if nested_aliases and tail:
            sub, sub_tail = self._match_compact_head(tail, nested_aliases)
            if sub:
                return " ".join([x for x in (head, sub, sub_tail) if x]).strip()
        return " ".join([x for x in (head, tail) if x]).strip()

    def _parse_jh_command_text(self, raw: str):
        clean = self._plain_trigger_text(raw)
        if not clean:
            return None
        has_slash = clean.startswith("/")
        if has_slash:
            clean = clean[1:].strip()
        prefix = str(getattr(self, "command_prefix", "jh") or "jh").strip() or "jh"
        if not clean.lower().startswith(prefix.lower()):
            return None
        body = clean[len(prefix):].strip()
        parsed = {"action": "", "rest": "", "recognized": False, "slash": has_slash, "raw": raw}
        if not body:
            parsed.update(action="help", recognized=True)
            return parsed
        command_groups = [
            ("test_mode", ["测试模式", "调试模式", "debug", "testmode", "trace", "test"]),
            ("help", ["帮助", "help", "h", "?"]),
            ("delegate_admin", ["传授魔法", "授予魔法", "收回魔法", "管理员"]),
            ("auto_optimize", ["重置lora", "重置LoRA", "清空lora", "清空LoRA", "重置角色lora", "重置角色LoRA", "自动优化", "自动体检", "优化档案", "优化lora", "优化LoRA"]),
            ("role_list", ["可以画的角色列表", "可以画角色列表", "可画角色列表", "可以画的角色", "可画角色", "角色列表", "角色档案列表", "档案列表"]),
            ("delete_role", ["删除角色", "删角色"]),
            ("style_preset", ["切换画风", "切画风", "切换风格", "画风", "风格", "style", "preset"]),
            ("model", ["模型族", "模型", "model", "models"]),
            ("lora", ["lora", "LoRA"]),
            ("civitai", ["civitai", "站内"]),
            ("magic", ["magic", "gpt", "魔法"]),
            ("self_update", ["更新画图", "画图更新"]),
            ("recall", ["自动撤回", "撤回", "recall"]),
            ("audit", ["图片审核", "图片鉴黄", "鉴黄", "audit_image", "imageaudit"]),
            ("nsfw", ["自审查", "自审", "审核", "nsfw", "review"]),
            ("status", ["状态", "status"]),
            ("generation_stats", ["排行", "排行榜", "统计", "计数", "计数器", "画图排行", "生成排行", "今日排行"]),
            ("prompt_notebook", ["看本本", "本本", "提示词本", "promptbook", "notebook", "savedprompt"]),
            ("prompt_note", ["记下来", "记一下", "记住", "promptnote", "saveprompt"]),
            ("seed", ["随机种子", "固定种子", "种子", "seed"]),
            ("negative", ["负面", "neg", "negative"]),
            ("workflow", ["工作流", "workflow", "wf"]),
            ("lora_import", ["下载lora", "导入lora", "下lora", "选lora", "找lora", "搜lora", "搜索lora", "导入", "下载", "选择", "选"]),
        ]
        for action, aliases in command_groups:
            head, rest = self._match_compact_head(body, aliases)
            if not head:
                continue
            parsed.update(action=action, rest=rest, recognized=True, head=head)
            if action == "lora":
                parsed["rest"] = self._normalize_compact_subcommand_rest(
                    rest,
                    ["角色档案", "档案", "alias", "别名", "role", "角色词", "角色提示词", "diagnose", "diag", "诊断", "排查", "status", "状态", "current", "当前", "list", "ls", "列表", "refresh", "刷新", "reload", "off", "none", "disable", "关闭", "禁用", "webui", "config", "配置", "reset", "跟随", "use", "set", "切换", "使用", "help", "帮助"],
                    nested={
                        "档案": ["列表", "list", "ls", "删除", "del", "delete", "rm"],
                        "角色档案": ["列表", "list", "ls", "删除", "del", "delete", "rm"],
                    },
                )
            elif action == "model":
                parsed["rest"] = self._normalize_compact_subcommand_rest(rest, ["列表", "list", "ls", "切换", "use", "set", "状态", "当前", "current"])
            elif action == "workflow":
                parsed["rest"] = self._normalize_compact_subcommand_rest(rest, ["当前", "状态", "current", "列表", "list", "ls", "切换", "use", "set"])
            elif action == "auto_optimize":
                parsed["rest"] = self._normalize_compact_subcommand_rest(
                    rest,
                    [
                        "apply", "应用", "确认", "重置", "reset", "清空", "写入",
                        "files", "file", "文件", "删文件", "删除文件", "下载文件", "模型文件", "lora文件", "全部", "彻底", "all", "purge",
                        "查看备份", "备份", "backups", "backup", "list",
                    ],
                    nested={
                        "apply": ["files", "file", "文件", "删文件", "删除文件", "下载文件", "模型文件", "lora文件", "全部", "彻底", "all", "purge"],
                        "应用": ["files", "file", "文件", "删文件", "删除文件", "下载文件", "模型文件", "lora文件", "全部", "彻底", "all", "purge"],
                        "确认": ["files", "file", "文件", "删文件", "删除文件", "下载文件", "模型文件", "lora文件", "全部", "彻底", "all", "purge"],
                        "重置": ["files", "file", "文件", "删文件", "删除文件", "下载文件", "模型文件", "lora文件", "全部", "彻底", "all", "purge"],
                        "reset": ["files", "file", "文件", "删文件", "删除文件", "下载文件", "模型文件", "lora文件", "全部", "彻底", "all", "purge"],
                    },
                )
            elif action == "lora_import":
                parsed["force_auto"] = str(head).lower() in {"找lora", "搜lora", "搜索lora"}
            return parsed
        return parsed

    async def _dispatch_jh_parsed_command(self, event: AstrMessageEvent, parsed: dict):
        if not parsed or not parsed.get("recognized"):
            return
        action = parsed.get("action")
        rest = str(parsed.get("rest") or "").strip()
        if action == "test_mode":
            async for result in self._handle_test_mode_command(event, rest):
                yield result
            return
        if action == "help":
            user_id = str(event.get_sender_id())
            yield self._build_jh_help_result(event, is_admin=self._can_manage_lora(user_id), is_super_admin=self._is_super_admin(user_id))
            return
        if action == "delegate_admin":
            async for result in self._yield_from_command(event, f"酒狐传授魔法 {rest}".strip(), self.cmd_delegate_magic_admin):
                yield result
            return
        if action == "role_list":
            async for result in self._handle_paintable_roles_command(event, rest):
                yield result
            return
        if action == "delete_role":
            async for result in self._handle_delete_role_command(event, rest):
                yield result
            return
        if action == "style_preset":
            async for result in self._handle_style_preset_command(event, rest):
                yield result
            return
        if action == "model":
            async for result in self._handle_model_family_command(event, rest):
                yield result
            return
        if action == "lora":
            async for result in self._yield_from_command(event, f"/comfy_lora {rest}".strip(), self.cmd_comfy_lora):
                yield result
            return
        if action == "civitai":
            async for result in self._yield_from_command(event, f"/comfy_civitai {rest}".strip(), self.cmd_comfy_civitai):
                yield result
            return
        if action == "lora_import":
            async for result in self._handle_jh_lora_import_short(event, rest, force_auto=bool(parsed.get("force_auto"))):
                yield result
            return
        if action == "auto_optimize":
            async for result in self._handle_lora_auto_optimize_command(event, rest):
                yield result
            return
        if action == "magic":
            async for result in self._handle_gpt_magic_raw(event, f"jh magic {rest}".strip()):
                yield result
            return
        if action == "self_update":
            try:
                event.set_extra("comfy_self_update_handled", True)
            except Exception:
                pass
            async for result in self._handle_self_update_command(event, f"酒狐更新画图 {rest}".strip()):
                yield result
            return
        if action == "recall":
            async for result in self._handle_recall_settings_command(event, rest):
                yield result
            return
        if action == "audit":
            async for result in self._handle_image_audit_command(event, rest):
                yield result
            return
        if action == "nsfw":
            async for result in self._handle_nsfw_review_command(event, rest):
                yield result
            return
        if action == "status":
            async for result in self._handle_jh_status_command(event):
                yield result
            return
        if action == "generation_stats":
            async for result in self._handle_generation_stats_command(event, rest):
                yield result
            return
        if action == "prompt_notebook":
            async for result in self._handle_prompt_notebook_command(event, f"{self.command_prefix}看本本 {rest}".strip()):
                yield result
            return
        if action == "prompt_note":
            async for result in self._handle_prompt_note_command(event, f"{self.command_prefix}记下来 {rest}".strip()):
                yield result
            return
        if action == "workflow":
            tokens = rest.split()
            if tokens and tokens[0].lower() in ("列表", "list", "ls"):
                temp, handler = "/comfy_ls", self.cmd_comfy_list
            elif tokens and tokens[0].lower() in ("切换", "use", "set"):
                temp, handler = f"/comfy_use {' '.join(tokens[1:]).strip()}".strip(), self.cmd_comfy_use
            else:
                temp, handler = "/当前工作流", self.cmd_comfy_current
            async for result in self._yield_from_command(event, temp, handler):
                yield result
            return
        if action == "negative":
            async for result in self._handle_negative_prompt_command(event, rest):
                yield result
            return
        if action == "seed":
            async for result in self._handle_seed_command(event, rest):
                yield result
            return
        return

    # ===== 酒狐来点 / jh 普通消息入口 =====
    @filter.event_message_type(filter.EventMessageType.ALL, priority=10)
    async def _jh_plain_paint_entry(self, event: AstrMessageEvent):
        """统一捕获 jh 管理命令；绘图只接受明确的“酒狐来点”。"""
        raw_candidates = self._event_plain_text_candidates(event)
        if not raw_candidates:
            raw_candidates = [self._plain_trigger_text(getattr(event, "message_str", ""))]
        await self._remember_look_recent_images_from_event(event, raw_candidates=raw_candidates)
        await self._remember_look_private_images_from_event(event, raw_candidates=raw_candidates)

        prompt_note_title_handled, prompt_note_title_result = await self._handle_prompt_note_pending_title(event, raw_candidates)
        if prompt_note_title_handled:
            try:
                event.stop_event()
                event.should_call_llm(True)
            except Exception:
                pass
            if prompt_note_title_result:
                await self._send_result_safely(event, prompt_note_title_result, context="prompt_note_title")
            return

        parsed_jh = None
        parsed_raw = ""
        for candidate in raw_candidates:
            parsed = self._parse_jh_command_text(candidate)
            if parsed and parsed.get("recognized"):
                parsed_jh = parsed
                parsed_raw = candidate
                break
        if parsed_jh:
            try:
                event.stop_event()
                event.should_call_llm(True)
            except Exception:
                pass
            logger.info(f"[ComfyUI] 捕获统一 jh 指令: action={parsed_jh.get('action')} raw={str(parsed_raw)[:40]}")
            await self._trace_test_mode(
                event,
                "command_entry",
                payload={
                    "action": parsed_jh.get("action"),
                    "rest": parsed_jh.get("rest"),
                    "raw": str(parsed_raw)[:200],
                    "user": event.get_sender_id(),
                },
            )
            async for result in self._dispatch_jh_parsed_command(event, parsed_jh):
                await self._send_result_safely(event, result, context="jh_unified_entry")
            return

        command_candidates = [text for text in raw_candidates if text and not text.startswith("/")]
        if not command_candidates:
            return

        gallery_register_raw = next((text for text in command_candidates if self._is_gallery_register_trigger(text, event=event)), "")
        if gallery_register_raw:
            try:
                event.stop_event()
                event.should_call_llm(True)
            except Exception:
                pass
            logger.info(f"[ComfyUI] 捕获普通消息酒狐注册，user={event.get_sender_id()}")
            async for result in self._handle_gallery_register_command(event, gallery_register_raw):
                await self._send_result_safely(event, result, context="gallery_register")
            return

        prompt_note_raw = next((text for text in command_candidates if self._is_prompt_note_trigger(text, event=event)), "")
        if prompt_note_raw:
            try:
                event.stop_event()
                event.should_call_llm(True)
            except Exception:
                pass
            logger.info(f"[ComfyUI] 捕获普通消息酒狐记下来，user={event.get_sender_id()}")
            async for result in self._handle_prompt_note_command(event, prompt_note_raw):
                await self._send_result_safely(event, result, context="prompt_note")
            return

        prompt_notebook_raw = next((text for text in command_candidates if self._is_prompt_notebook_trigger(text, event=event)), "")
        if prompt_notebook_raw:
            try:
                event.stop_event()
                event.should_call_llm(True)
            except Exception:
                pass
            logger.info(f"[ComfyUI] 捕获普通消息酒狐看本本，user={event.get_sender_id()}")
            async for result in self._handle_prompt_notebook_command(event, prompt_notebook_raw):
                await self._send_result_safely(event, result, context="prompt_notebook")
            return

        test_mode_raw = next((text for text in raw_candidates if self._is_test_mode_trigger(text, event=event)), "")
        if test_mode_raw:
            try:
                event.stop_event()
                event.should_call_llm(True)
            except Exception:
                pass
            logger.info(f"[ComfyUI] 捕获测试模式命令: text={test_mode_raw[:24]}")
            rest = self._parse_plain_test_mode_command(test_mode_raw) or ""
            async for result in self._handle_test_mode_command(event, rest):
                await self._send_result_safely(event, result, context="test_mode_plain_entry")
            return

        audit_raw = next((text for text in raw_candidates if self._is_image_audit_trigger(text, event=event)), "")
        if audit_raw:
            try:
                event.stop_event()
                event.should_call_llm(True)
            except Exception:
                pass
            logger.info(f"[ComfyUI] 捕获普通消息酒狐审核，text={audit_raw[:20]}")
            async for result in self._handle_image_audit_command(event, audit_raw):
                await self._send_result_safely(event, result, context="image_audit_plain_entry")
            return

        look_raw = next((text for text in command_candidates if self._is_look_trigger(text, event=event)), "")
        if look_raw:
            try:
                event.stop_event()
                event.should_call_llm(True)
            except Exception:
                pass
            logger.info(f"[ComfyUI] 捕获普通消息酒狐看看，user={event.get_sender_id()}")
            async for result in self._handle_look_command(event, look_raw):
                await self._send_result_safely(event, result, context="look_plain_entry")
            return

        stats_raw = next((text for text in command_candidates if self._is_generation_stats_trigger(text, event=event)), "")
        if stats_raw:
            try:
                event.stop_event()
                event.should_call_llm(True)
            except Exception:
                pass
            logger.info(f"[ComfyUI] 捕获普通消息酒狐排行，user={event.get_sender_id()}")
            stats_rest = self._generation_stats_command_body(stats_raw)
            async for result in self._handle_generation_stats_command(event, stats_rest):
                await self._send_result_safely(event, result, context="generation_stats_plain_entry")
            return

        delegate_raw = next((text for text in command_candidates if self._is_delegate_magic_trigger(text, event=event)), "")
        if delegate_raw:
            try:
                event.stop_event()
                event.should_call_llm(True)
            except Exception:
                pass
            logger.info(f"[ComfyUI] 捕获普通消息酒狐传授魔法，user={event.get_sender_id()}")
            async for result in self._yield_from_command(event, delegate_raw, self.cmd_delegate_magic_admin):
                await self._send_result_safely(event, result, context="delegate_magic_plain_entry")
            return

        favorite_raw = next((text for text in command_candidates if self._is_favorite_trigger(text, event=event)), "")
        if favorite_raw:
            try:
                event.stop_event()
                event.should_call_llm(True)
            except Exception:
                pass
            logger.info(f"[ComfyUI] 捕获普通消息酒狐收藏，user={event.get_sender_id()}")
            async for result in self._handle_favorite_command(event, favorite_raw):
                await self._send_result_safely(event, result, context="favorite_plain_entry")
            return

        update_raw = next((text for text in raw_candidates if self._is_self_update_trigger(text, event=event)), "")
        if update_raw:
            try:
                event.set_extra("comfy_self_update_handled", True)
                event.stop_event()
                event.should_call_llm(True)
            except Exception:
                pass
            logger.info(f"[ComfyUI] 捕获普通消息酒狐更新画图，text={update_raw[:24]}")
            async for result in self._handle_self_update_command(event, update_raw):
                await self._send_result_safely(event, result, context="self_update_plain_entry")
            return

        magic_raw = next((text for text in command_candidates if self._is_gpt_magic_trigger(text)), "")
        if magic_raw:
            try:
                event.stop_event()
                event.should_call_llm(True)
            except Exception:
                pass
            logger.info("[GPT Magic] 捕获普通消息酒狐魔法")
            async for result in self._handle_gpt_magic_raw(event, magic_raw):
                await self._send_result_safely(event, result, context="gpt_magic_plain_entry")
            return

        video_prompt = None
        video_mode = ""
        for candidate in command_candidates:
            video_prompt, video_mode = self._extract_plain_video_request(candidate, event=event)
            if video_prompt is not None:
                break
        if video_prompt is not None:
            try:
                event.stop_event()
                event.should_call_llm(True)
            except Exception:
                pass
            logger.info(f"[ComfyUI] 捕获普通消息视频生成，mode={video_mode} prompt_len={len(video_prompt)}")
            async for result in self._handle_video_prompt(event, video_prompt, direct_send=False, video_mode=video_mode or "local"):
                await self._send_result_safely(event, result, context="plain_video")
            return

        selection_raw = next(
            (text for text in command_candidates if re.fullmatch(r'\d{1,2}', text) and self._can_import_civitai_selection(event, text)),
            "",
        )
        if selection_raw:
            try:
                event.stop_event()
                event.should_call_llm(True)
            except Exception:
                pass
            logger.info(f"[ComfyUI] 捕获 LoRA 搜索序号回复: {selection_raw}")
            async for result in self._handle_jh_lora_import_short(event, selection_raw, force_auto=False):
                await self._send_result_safely(event, result, context="civitai_selection")
            return

        prefix = str(getattr(self, "command_prefix", "jh") or "jh").strip() or "jh"
        lower_prefix = prefix.lower()
        raw = command_candidates[0]
        prompt = None
        for candidate in command_candidates:
            prompt = self._extract_plain_paint_prompt(candidate, event=event)
            if prompt is not None:
                raw = candidate
                break

        short_import = None
        force_auto_import = False
        if prompt is None:
            for candidate in command_candidates:
                lower_candidate = candidate.lower()
                for keyword in (f"{prefix}导入", f"{prefix}下载lora", f"{prefix}下lora", f"{prefix}选lora", f"{prefix}找lora", f"{prefix}搜lora"):
                    if lower_candidate.startswith(keyword.lower()):
                        raw = candidate
                        short_import = candidate[len(keyword):].strip()
                        force_auto_import = keyword.lower() in {f"{prefix}找lora".lower(), f"{prefix}搜lora".lower()}
                        break
                if short_import is not None:
                    break
        if prompt is None and short_import is None:
            for candidate in command_candidates:
                lower_candidate = candidate.lower()
                if not lower_candidate.startswith(lower_prefix + " "):
                    continue
                body = candidate[len(prefix):].strip()
                body_tokens = body.split()
                head = body_tokens[0].lower() if body_tokens else ''
                if head in ('导入', '下载', '下载lora', '导入lora', '下lora', '选择', '选', '选lora', '找lora', '搜lora', '搜索lora'):
                    raw = candidate
                    short_import = body[len(body_tokens[0]):].strip()
                    force_auto_import = head in ('找lora', '搜lora', '搜索lora')
                    break

        if prompt is None and short_import is None:
            return

        try:
            event.stop_event()
            event.should_call_llm(True)
        except Exception:
            pass

        if short_import is not None:
            logger.info(f"[ComfyUI] 捕获普通消息 jh LoRA 导入，query_len={len(short_import)}")
            async for result in self._handle_jh_lora_import_short(event, short_import, force_auto=force_auto_import):
                await self._send_result_safely(event, result, context="civitai_search")
        else:
            logger.info(f"[ComfyUI] 捕获普通消息酒狐来点，prompt_len={len(prompt)}")
            async for result in self._handle_paint_prompt(event, prompt, direct_send=False):
                await self._send_result_safely(event, result, context="plain_paint")
        return

