    @filter.command("酒狐传授魔法", aliases={"酒狐授予魔法", "酒狐收回魔法", "酒狐管理员", "jh传授魔法"})
    async def cmd_delegate_magic_admin(self, event: AstrMessageEvent):
        user_id = str(event.get_sender_id())
        if not self._is_super_admin(user_id):
            yield event.plain_result("🚫 权限不足，只有超级管理员可以传授魔法")
            return

        raw = self._plain_trigger_text(event.message_str or "")
        rest, matched_head = self._delegate_magic_command_body(raw)
        if not matched_head:
            rest = raw
        lowered = rest.lower()
        target_ids = self._delegated_admin_target_ids(event, f"{raw}\n{rest}")
        if (not rest and not target_ids) or lowered in {"help", "帮助", "用法", "?"}:
            yield event.plain_result(
                "酒狐传授魔法用法\n"
                "━━━━━━━━━━━━━━━━━━\n"
                "酒狐传授魔法 @用户 / QQ  授予普通管理员\n"
                "酒狐传授魔法 取消 @用户 / QQ  收回普通管理员\n"
                "酒狐传授魔法 列表  查看普通管理员\n"
                "普通管理员可用：找 LoRA、导入 LoRA、删除角色、角色列表、酒狐收藏。\n"
                "不可用：画风切换、模型切换、工作流、锁定、自更新等超级管理员功能。"
            )
            return
        if lowered in {"list", "ls", "列表", "查看"}:
            yield event.plain_result(self._delegated_admin_list_text())
            return

        revoke = (
            bool(re.search(r"^(?:取消|删除|移除|收回|撤销|revoke|remove|del)(?:\s|$)", rest, flags=re.I))
            or "收回魔法" in str(matched_head or "")
        )
        if not target_ids:
            yield event.plain_result("没找到要传授的 QQ。用法：酒狐传授魔法 @用户 或 酒狐传授魔法 123456")
            return

        changed = []
        skipped = []
        records = dict(getattr(self, "normal_admin_records", {}) or {})
        if revoke:
            for target in target_ids:
                if target in records:
                    records.pop(target, None)
                    changed.append(target)
                else:
                    skipped.append(target)
            self.normal_admin_records = records
            self._save_delegated_admin_records()
            if changed:
                yield event.plain_result(f"已收回普通管理员：{'、'.join(changed)}")
            else:
                yield event.plain_result(f"这些 QQ 本来就不是普通管理员：{'、'.join(skipped)}")
            return

        for target in target_ids:
            if self._is_super_admin(target):
                skipped.append(f"{target}（已是超级管理员）")
                continue
            record = records.get(target) or {}
            record.update({
                "user_id": target,
                "granted_by": user_id,
                "granted_by_name": self._sender_display_name(event),
                "granted_at": time.strftime("%Y-%m-%d %H:%M:%S"),
                "permissions": ["lora_search_import", "lora_delete_role", "role_list", "favorite"],
            })
            records[target] = record
            changed.append(target)
        self.normal_admin_records = records
        self._save_delegated_admin_records()
        lines = []
        if changed:
            lines.append(f"已传授普通管理员：{'、'.join(changed)}")
            lines.append("可用：找 LoRA、导入 LoRA、删除角色、角色列表、酒狐收藏。")
        if skipped:
            lines.append(f"跳过：{'、'.join(skipped)}")
        yield event.plain_result("\n".join(lines).strip() or "没有变更")

