    def _generation_request_text(self, event: AstrMessageEvent, meta: dict = None) -> str:
        meta = meta or {}
        for candidate in self._event_plain_text_candidates(event):
            candidate = str(candidate or "").strip()
            if candidate:
                return candidate
        for key in ("raw_prompt", "request_prompt", "user_prompt"):
            value = str(meta.get(key) or "").strip()
            if value:
                return value
        return ""

    def _build_generation_request_node(self, event: AstrMessageEvent, meta: dict = None):
        sender_id = str(event.get_sender_id() or "").strip()
        request_text = self._generation_request_text(event, meta=meta)
        if not request_text:
            return None
        content = f"生成请求"
        if sender_id:
            content += f"（QQ: {sender_id}）"
        content += f"\n{request_text}"
        return Node(
            uin=self._safe_sender_id_int(event),
            name=self._sender_display_name(event),
            content=[Plain(content)],
        )

    def _format_elapsed(self, seconds) -> str:
        try:
            seconds = float(seconds or 0)
        except Exception:
            seconds = 0.0
        if seconds >= 60:
            minutes = int(seconds // 60)
            remain = seconds - minutes * 60
            return f"{minutes}分{remain:.1f}秒"
        return f"{seconds:.2f}秒"

    def _format_generation_info(self, prompt: str, meta: dict = None, index: int = None, total: int = None, intro_text: str = None) -> str:
        """生成转发消息里的说明文本：提示词、耗时、LoRA、工作流等。"""
        meta = meta or {}
        output_conf = self.config.get("output_settings", {}) if isinstance(self.config.get("output_settings", {}), dict) else {}
        include_prompt = bool(output_conf.get("include_prompt", True))
        include_time = bool(output_conf.get("include_generation_time", True))
        include_seed = bool(output_conf.get("include_seed", True))
        include_lora = bool(output_conf.get("include_lora", True))

        lines = []
        if intro_text:
            intro_text = str(intro_text).strip()
            if intro_text:
                lines.append(intro_text)
                lines.append("")

        title = "🎨 ComfyUI 绘图结果"
        if index is not None and total:
            title += f" ({index}/{total})"
        lines.append(title)
        lines.append("━━━━━━━━━━━━━━━━━━")

        if include_time:
            lines.append(f"⏱️ 画图耗时：{self._format_elapsed(meta.get('elapsed_seconds', 0))}")
        if include_workflow:
            lines.append(f"🧠 工作流：{meta.get('workflow', getattr(self.api, 'wf_filename', '未知'))}")
        model_names = meta.get("model_names") or meta.get("checkpoint_name") or meta.get("model_name") or ""
        if isinstance(model_names, (list, tuple)):
            model_names = "、".join([str(x) for x in model_names if str(x).strip()])
        model_names = str(model_names or "").strip()
        model_family = str(meta.get("model_family_label") or meta.get("model_family") or "").strip()
        if model_family or model_names:
            if model_family and model_names:
                lines.append(f"🧬 模型：{model_family} / {model_names}")
            else:
                lines.append(f"🧬 模型：{model_family or model_names}")
        if meta.get("style_preset_label"):
            params = []
            if meta.get("generation_width") and meta.get("generation_height"):
                params.append(f"{meta.get('generation_width')}x{meta.get('generation_height')}")
            if meta.get("generation_sampler"):
                scheduler = f"/{meta.get('generation_scheduler')}" if meta.get("generation_scheduler") else ""
                params.append(f"{meta.get('generation_sampler')}{scheduler}")
            if meta.get("generation_steps"):
                params.append(f"{meta.get('generation_steps')}步")
            if meta.get("generation_cfg"):
                params.append(f"CFG {meta.get('generation_cfg')}")
            suffix = f"（{'，'.join(params)}）" if params else ""
            lines.append(f"🎨 内置画风：{meta.get('style_preset_label')}{suffix}")
        if meta.get("mode") == "img2img":
            denoise = meta.get("img2img_denoise")
            denoise_text = f"（重绘幅度 {denoise}）" if denoise is not None else ""
            mode_label = "图生图"
            if meta.get("img2img_mode_hint") == "character_replace":
                mode_label = "图生图 / 角色替换"
            lines.append(f"🖼️ 模式：{mode_label}{denoise_text}")
            if meta.get("img2img_reverse_prompt"):
                lines.append("👁️ 视觉反推：已生效")
            elif meta.get("img2img_reverse_warning"):
                lines.append(f"⚠️ 视觉反推：{meta.get('img2img_reverse_warning')}")
            if meta.get("img2img_control_strength") is not None:
                if meta.get("img2img_mode_hint") == "illustrious_img2img":
                    ill_nodes = meta.get("img2img_illustrious_nodes") if isinstance(meta.get("img2img_illustrious_nodes"), dict) else {}
                    refine_text = (
                        f"二采 {meta.get('img2img_refine_denoise', '-')}"
                        if int(ill_nodes.get("samplers") or 0) > 1
                        else "单采"
                    )
                    lines.append(
                        f"🧭 Illustrious 控制：Depth CN {meta.get('img2img_control_strength')} / "
                        f"{refine_text}, "
                        f"长边 {meta.get('img2img_scale_to_length', '-')}"
                    )
                    if meta.get("oom_retry_after_free"):
                        lines.append("♻️ 显存：已清理后重试")
                else:
                    lines.append(
                        f"🧭 Anima 控制：LLLite {meta.get('img2img_control_strength')} / "
                        f"end {meta.get('img2img_control_end_percent', '-')}, "
                        f"预处理 {meta.get('img2img_preprocessor', '-')}"
                    )
        if meta.get("multi_lora_staged"):
            lines.append(
                f"Multi-LoRA: staged inpaint / roles {meta.get('multi_lora_role_count', '-')} / "
                f"passes {meta.get('multi_lora_stage_count', '-')}"
            )
        if include_lora:
            lora_name = str(meta.get("lora_name") or "").strip()
            lora_nodes = meta.get("lora_node_ids") or []
            try:
                lora_strength_active = (
                    abs(float(meta.get("strength_model") or 0)) > 0.0001
                    or abs(float(meta.get("strength_clip") or 0)) > 0.0001
                )
            except Exception:
                lora_strength_active = bool(lora_name)
            if lora_name and lora_strength_active:
                lines.append(f"🧩 LoRA：{lora_name}（节点 {', '.join(map(str, lora_nodes))}）")
            elif lora_nodes:
                lines.append(f"🧩 LoRA：未启用（已旁路节点 {', '.join(map(str, lora_nodes))}）")
            else:
                lines.append("🧩 LoRA：未启用 / 工作流默认")
            if meta.get("lora_strength_cap_note"):
                lines.append(f"🎚️ LoRA 强度：{meta.get('lora_strength_cap_note')}")
            style_lora_name = str(meta.get("style_lora_name") or "").strip()
            style_lora_nodes = meta.get("style_lora_node_ids") or []
            if style_lora_name:
                if style_lora_nodes:
                    lines.append(f"🎨 画风 LoRA：{style_lora_name}（节点 {', '.join(map(str, style_lora_nodes))}）")
                else:
                    lines.append(f"🎨 画风 LoRA：{style_lora_name}")
            if meta.get("profile_character"):
                lines.append(f"🎭 角色档案：{meta.get('profile_character')}")
            if meta.get("lora_warning"):
                lines.append(f"⚠️ {meta.get('lora_warning')}")
            if meta.get("style_lora_warning"):
                lines.append(f"⚠️ {meta.get('style_lora_warning')}")
            if meta.get("family_guard_warning"):
                lines.append(f"⚠️ {meta.get('family_guard_warning')}")
        if include_seed and meta.get("seed") is not None:
            seed_source = str(meta.get("seed_source") or "").strip()
            source_label = {"random": "随机", "fixed": "固定", "prompt": "本次指定", "explicit": "指定"}.get(seed_source, seed_source)
            lines.append(f"🎲 Seed：{meta.get('seed')}" + (f"（{source_label}）" if source_label else ""))
        if meta.get("nsfw_self_review_blocked"):
            lines.append("🛡️ 自审查：未通过酒狐一级自审查，图片已改发加密压缩包")

        if include_prompt:
            lines.append("")
            lines.append("📝 Prompt：")
            lines.append(str(prompt or "").strip())

        return "\n".join(lines).strip()

    def _comfy_image_in_forward(self) -> bool:
        output_conf = self.config.get("output_settings", {}) if isinstance(self.config.get("output_settings", {}), dict) else {}
        return bool(output_conf.get("comfy_image_in_forward", True))

    def _config_bool(self, value, default: bool = True) -> bool:
        if value is None:
            return bool(default)
        if isinstance(value, bool):
            return value
        text = str(value).strip().lower()
        if text in {"0", "false", "off", "no", "none", "disable", "disabled", "关闭"}:
            return False
        if text in {"1", "true", "on", "yes", "enable", "enabled", "开启"}:
            return True
        return bool(default)

    def _output_watermark_options(self) -> dict:
        output_conf = self.config.get("output_settings", {}) if isinstance(self.config.get("output_settings", {}), dict) else {}
        watermark_conf = output_conf.get("watermark", {}) if isinstance(output_conf.get("watermark", {}), dict) else {}
        enabled = watermark_conf.get("enabled", output_conf.get("watermark_enabled", True))
        watermark_size = (
            watermark_conf.get("size")
            if watermark_conf.get("size") not in (None, "")
            else watermark_conf.get("watermark_size")
        )
        if watermark_size in (None, ""):
            watermark_size = output_conf.get("watermark_size", output_conf.get("watermark_width_ratio", 0.24))
        return {
            "enabled": self._config_bool(enabled, True),
            "watermark_path": str(
                watermark_conf.get("path")
                or output_conf.get("watermark_path")
                or DEFAULT_WATERMARK_PATH
            ),
            "position": str(watermark_conf.get("position") or output_conf.get("watermark_position") or "bottom_left"),
            "width_ratio": watermark_conf.get("width_ratio", watermark_size),
            "opacity": watermark_conf.get("opacity", output_conf.get("watermark_opacity", 0.76)),
            "margin_ratio": watermark_conf.get("margin_ratio", output_conf.get("watermark_margin_ratio", 0.035)),
        }

    def _apply_output_watermark(self, image_path: Path, source: str = "comfyui", force: bool = False) -> dict:
        options = self._output_watermark_options()
        if not options.get("enabled", True) and not force:
            return {"applied": False, "reason": "disabled"}
        info = apply_watermark_to_image_file(
            image_path,
            watermark_path=options.get("watermark_path"),
            width_ratio=options.get("width_ratio", 0.24),
            opacity=options.get("opacity", 0.76),
            margin_ratio=options.get("margin_ratio", 0.035),
            position=options.get("position", "bottom_left"),
        )
        if info.get("applied"):
            logger.info(f"[ComfyUI] 已添加酒狐水印 | source={source} | image={Path(image_path).name}")
        else:
            logger.warning(f"[ComfyUI] 酒狐水印添加失败 | source={source} | {info.get('reason') or '-'}")
        return info

